1	// Proprietary in-portal DB manager — query transport to a hosting node's MySQL.
2	//
3	// SECURITY MODEL (read before touching this file):
4	//
5	//   * ISOLATION IS THE MYSQL GRANT, NOT AN APP CHECK. Every query runs
6	//     authenticated as the account's SCOPED manager user (`<username>_mgr`),
7	//     which is granted on `<username>\_%`.* ONLY (see buildDbMgrGrantSql). MySQL
8	//     itself refuses that user any access to another tenant's databases, to the
9	//     `mysql`/`sys`/`performance_schema` system schemas, and — being a db-scoped
10	//     grant — to FILE/PROCESS/SUPER (so no LOAD_FILE / INTO OUTFILE file reads).
11	//     `information_schema` stays readable but MySQL filters its rows to objects
12	//     the connecting user can see, i.e. this account's own databases. The app
13	//     ALSO validates the target db belongs to the account (defence in depth), but
14	//     even a bug there cannot breach the grant.
15	//
16	//   * PROTOCOL-LEVEL TRANSPORT — NO `mysql` CLI, EVER. The customer's SQL is run
17	//     through the `mysql2` protocol driver, which speaks the MySQL wire protocol
18	//     directly. It is NOT a command-line client, so it has NO in-band
19	//     meta-command interpreter: `\!` (shell-out), `\.`/`source` (read a node
20	//     file), `\T`/`tee` (write a node file) are CLI-only constructs and are sent
21	//     verbatim to the server as ordinary (invalid) SQL — they never execute on
22	//     the node. This is the fix for the mysql-CLI meta-command RCE: there is no
23	//     client-side interpreter to abuse, and the session authenticates as the
24	//     scoped `_mgr` user (never root), so the MySQL grant is the sole boundary.
25	//
26	//   * WHY WE STILL SSH AS ROOT (BUT ONLY TO TUNNEL). The node's MySQL is bound to
27	//     localhost and never exposed. We reach it by opening the platform's existing
28	//     root SSH connection (same credential the provisioner uses) and asking it to
29	//     `forwardOut` a direct-tcpip channel to 127.0.0.1:3306 on the node. That
30	//     channel is handed to `mysql2` as its socket. Root SSH is used ONLY as an
31	//     encrypted tunnel to localhost:3306 — it never runs a shell command and
32	//     never launches a mysql client, so the tenant's SQL can only ever reach the
33	//     MySQL server as the scoped, grant-confined user.
34	//
35	//   * SQL IS NEVER INTERPOLATED INTO A SHELL, NOR A CLI ARGV. Identifiers we
36	//     generate (db name, mgr user) are charset-validated; the mgr password is a
37	//     generated `[A-Za-z0-9]` secret passed only over the authenticated wire
38	//     handshake. The whole run is byte-capped, row-capped, and bounded by a
39	//     server-side statement cap AND a JS-side timeout that tears the connection
40	//     down, so a runaway/huge query can't hang or OOM us.
41	//
42	// This module is plain (non-"use server") + synchronous-friendly so the server
43	// actions in lib/actions-hosting-db.ts can call it directly, exactly like
44	// lib/hosting-fs.ts does for the file manager.
45	
46	import { Client, type ClientChannel } from "ssh2";
47	import mysql from "mysql2/promise";
48	import { escape as sqlEscape } from "mysql2";
49	import { decryptSecret } from "./crypto-box";
50	import { isValidDbIdentifier } from "./hosting";
51	
52	export type DbNodeTarget = {
53	  sshHost: string;
54	  sshPort: number;
55	  rootPassword: string;
56	  mgrUser: string;
57	  mgrPassword: string;
58	};
59	
60	/** Build the transport target for an account: the node's root SSH credential (to
61	 *  open the tunnel to localhost:3306) plus the account's scoped manager MySQL
62	 *  credential (what the mysql2 session actually authenticates as). Returns null
63	 *  until the manager user has been provisioned on the node. Lives in this plain
64	 *  module (not the "use server" actions file) because it is synchronous. */
65	export function dbTargetFor(a: {
66	  node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null };
67	  dbMgrUser: string | null;
68	  dbMgrPassEnc: string | null;
69	}): DbNodeTarget | null {
70	  const rootPassword = a.node.rootPasswordEnc ? decryptSecret(a.node.rootPasswordEnc) : null;
71	  const mgrPassword = a.dbMgrPassEnc ? decryptSecret(a.dbMgrPassEnc) : null;
72	  if (!rootPassword || !a.dbMgrUser || !mgrPassword) return null;
73	  return { sshHost: a.node.sshHost, sshPort: a.node.sshPort, rootPassword, mgrUser: a.dbMgrUser, mgrPassword };
74	}
75	
76	const CONNECT_TIMEOUT_MS = 20_000;
77	/** Hard ceiling on a single query, enforced on BOTH ends: a server-side statement
78	 *  cap (max_execution_time / max_statement_time) and a JS timer that destroys the
79	 *  mysql2 connection + tears down the SSH channel. */
80	const QUERY_TIMEOUT_S = 15;
81	const QUERY_TIMEOUT_MS = (QUERY_TIMEOUT_S + 5) * 1000;
82	/** Cap the bytes we retain from a result so a `SELECT * FROM huge` can't OOM the
83	 *  app node — we stop reading (destroy the connection) and mark it truncated. */
84	const MAX_OUTPUT_BYTES = 2 * 1024 * 1024; // 2 MiB
85	/** Cap on the SQL we will ship to the node (a sane upper bound; the UI edits are
86	 *  tiny and even a pasted query is far under this). */
87	export const MAX_SQL_BYTES = 64 * 1024;
88	
89	export type QueryResult = {
90	  columns: string[];
91	  rows: string[][];
92	  /** true when we stopped at MAX_OUTPUT_BYTES / the row cap and more data exists. */
93	  truncated: boolean;
94	  /** non-null on a MySQL/transport error (already trimmed for display). */
95	  error: string | null;
96	  /** ms the query took end-to-end (for the UI). */
97	  elapsedMs: number;
98	};
99	
100	function connectRoot(t: DbNodeTarget): Promise<Client> {
101	  const conn = new Client();
102	  return new Promise<Client>((resolve, reject) => {
103	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
104	    conn
105	      .on("ready", () => { clearTimeout(timer); resolve(conn); })
106	      .on("error", (e) => { clearTimeout(timer); reject(e); })
107	      .connect({ host: t.sshHost, port: t.sshPort, username: "root", password: t.rootPassword, readyTimeout: CONNECT_TIMEOUT_MS });
108	  });
109	}
110	
111	/** Open a direct-tcpip channel from the root SSH connection to the node's
112	 *  localhost MySQL. The returned Channel is a duplex stream we hand to mysql2 as
113	 *  its socket — MySQL stays bound to localhost on the node (never exposed). */
114	function forwardMysqlChannel(conn: Client): Promise<ClientChannel> {
115	  return new Promise<ClientChannel>((resolve, reject) => {
116	    const timer = setTimeout(() => reject(new Error("SSH tunnel to MySQL timed out")), CONNECT_TIMEOUT_MS);
117	    conn.forwardOut("127.0.0.1", 0, "127.0.0.1", 3306, (err, channel) => {
118	      clearTimeout(timer);
119	      if (err) return reject(err);
120	      resolve(channel);
121	    });
122	  });
123	}
124	
125	/**
126	 * Run one statement of SQL against `dbName` as the scoped manager user and return
127	 * the result set (or an error). The SQL is executed through the mysql2 protocol
128	 * driver over an SSH-forwarded channel to the node's localhost MySQL — there is
129	 * NO mysql CLI in the path, so client-side meta-commands (`\!`, source, tee)
130	 * cannot execute; they reach the server as ordinary SQL. `multipleStatements` is
131	 * off, so no stacked queries. Non-SELECT statements produce no rows (columns
132	 * empty) — the caller reports a generic success.
133	 */
134	export async function runScopedSql(t: DbNodeTarget, dbName: string, sql: string, params?: readonly unknown[]): Promise<QueryResult> {
135	  const started = Date.now();
136	  // Re-assert the shape of every value we authenticate/connect with (the caller
137	  // validates too — belt and braces). The mgr user + db name are OUR generated
138	  // identifiers; the password is generated [A-Za-z0-9].
139	  if (!isValidDbIdentifier(dbName)) return errResult(started, "invalid database name");
140	  if (!isValidDbIdentifier(t.mgrUser)) return errResult(started, "invalid manager user");
141	  if (!/^[A-Za-z0-9]{1,64}$/.test(t.mgrPassword)) return errResult(started, "invalid manager credential");
142	  const sqlText = String(sql ?? "");
143	  if (Buffer.byteLength(sqlText, "utf8") > MAX_SQL_BYTES) return errResult(started, "query too large");
144	
145	  let conn: Client | null = null;
146	  let channel: ClientChannel | null = null;
147	  let connection: mysql.Connection | null = null;
148	  try {
149	    conn = await connectRoot(t);
150	    channel = await forwardMysqlChannel(conn);
151	    // Authenticate as the SCOPED manager user over the forwarded stream. No CLI,
152	    // no root MySQL session — the grant on `<username>\_%`.* is the only boundary.
153	    connection = await mysql.createConnection({
154	      stream: channel,
155	      user: t.mgrUser,
156	      password: t.mgrPassword,
157	      database: dbName,
158	      multipleStatements: false, // one statement per run — no stacked-query surface
159	      dateStrings: true,         // DATE/DATETIME/TIMESTAMP as strings (match old display)
160	      supportBigNumbers: true,
161	      bigNumberStrings: true,    // no precision loss on BIGINT / DECIMAL
162	      connectTimeout: CONNECT_TIMEOUT_MS,
163	      charset: "utf8mb4_general_ci",
164	    });
165	    // Best-effort server-side statement cap. MySQL uses max_execution_time (ms,
166	    // SELECTs only); MariaDB uses max_statement_time (seconds). The value is our
167	    // own integer constant (no injection surface). Either may be absent — the JS
168	    // timeout below is the hard guard regardless.
169	    await connection.query(`SET SESSION max_execution_time = ${QUERY_TIMEOUT_S * 1000}`).catch(() => { /* */ });
170	    await connection.query(`SET SESSION max_statement_time = ${QUERY_TIMEOUT_S}`).catch(() => { /* */ });
171	
172	    return await streamQuery(connection, sqlText, started, params);
173	  } catch (e) {
174	    return errResult(started, e instanceof Error ? e.message : String(e));
175	  } finally {
176	    // Always tear everything down: mysql2 connection, forwarded channel, SSH.
177	    try { if (connection) await connection.end(); } catch { try { connection?.destroy(); } catch { /* */ } }
178	    try { channel?.end(); } catch { /* */ }
179	    try { conn?.end(); } catch { /* */ }
180	  }
181	}
182	
183	/**
184	 * Execute one statement via the mysql2 streaming (event-emitter) API on the
185	 * underlying core connection, enforcing the row + byte caps and a hard JS timeout.
186	 * Streaming (rather than a buffered `[rows]` await) lets us stop the server mid
187	 * result-set — destroying the connection — the instant either cap is hit, so a
188	 * `SELECT * FROM huge` can neither OOM us nor stay on the wire. `rowsAsArray`
189	 * yields positional arrays that preserve duplicate column names.
190	 */
191	function streamQuery(connection: mysql.Connection, sql: string, started: number, params?: readonly unknown[]): Promise<QueryResult> {
192	  return new Promise<QueryResult>((resolve) => {
193	    // The promise wrapper exposes the callback-style core connection as `.connection`;
194	    // only the core connection returns the streaming Query event-emitter.
195	    const core = (connection as unknown as { connection: any }).connection;
196	    const columns: string[] = [];
197	    const rows: string[][] = [];
198	    let bytes = 0;
199	    let truncated = false;
200	    let settled = false;
201	
202	    const finish = (r: QueryResult) => {
203	      if (settled) return;
204	      settled = true;
205	      clearTimeout(timer);
206	      resolve(r);
207	    };
208	    const finishOk = () => finish({ columns, rows, truncated, error: null, elapsedMs: Date.now() - started });
209	    const stopAtCap = () => {
210	      truncated = true;
211	      // Halt further transfer, then resolve with what we have.
212	      try { core.destroy(); } catch { /* */ }
213	      finishOk();
214	    };
215	
216	    const timer = setTimeout(() => {
217	      try { core.destroy(); } catch { /* */ }
218	      finish(errResult(started, "query timed out"));
219	    }, QUERY_TIMEOUT_MS);
220	
221	    let q: any;
222	    try {
223	      // When `params` are supplied, mysql2 substitutes each `?` with the escaped
224	      // literal for that value (client-side escaping) — a value can neither break
225	      // out of its quotes nor, with `multipleStatements` off, smuggle a second
226	      // statement. When absent, this is byte-for-byte the previous behaviour.
227	      q = params && params.length
228	        ? core.query({ sql, values: params as unknown[], rowsAsArray: true })
229	        : core.query({ sql, rowsAsArray: true });
230	    } catch (e) {
231	      return finish(errResult(started, e instanceof Error ? e.message : String(e)));
232	    }
233	    q.on("error", (err: Error) => finish(errResult(started, err?.message ?? String(err))));
234	    q.on("fields", (fields: any) => {
235	      // Emitted once per result set for SELECT-like statements; absent for OK packets.
236	      if (Array.isArray(fields)) for (const f of fields) columns.push(String(f?.name ?? ""));
237	    });
238	    q.on("result", (row: any) => {
239	      if (settled || truncated) return;
240	      // Non-SELECT statements emit an OK/result packet (not an array) → no rows.
241	      if (!Array.isArray(row)) return;
242	      if (rows.length >= MAX_ROWS) return stopAtCap();
243	      const out = new Array<string>(row.length);
244	      for (let i = 0; i < row.length; i++) {
245	        const s = cellToString(row[i]);
246	        out[i] = s;
247	        bytes += Buffer.byteLength(s, "utf8");
248	      }
249	      rows.push(out);
250	      if (bytes >= MAX_OUTPUT_BYTES) return stopAtCap();
251	    });
252	    q.on("end", () => finishOk());
253	  });
254	}
255	
256	/** Convert a mysql2 cell value to the display string the UI expects. SQL NULL maps
257	 *  to the NULL sentinel (the grid renders it as a muted "NULL"); dates already
258	 *  arrive as strings (dateStrings:true); Buffers are decoded as UTF-8. */
259	function cellToString(v: unknown): string {
260	  if (v === null || v === undefined) return NULL_CELL;
261	  if (typeof v === "string") return v;
262	  if (Buffer.isBuffer(v)) return v.toString("utf8");
263	  if (v instanceof Date) return v.toISOString();
264	  return String(v);
265	}
266	
267	function errResult(started: number, message: string): QueryResult {
268	  return { columns: [], rows: [], truncated: false, error: sanitizeError(message), elapsedMs: Date.now() - started };
269	}
270	
271	/** Trim + de-noise a MySQL/transport error for display (drop the leading
272	 *  `ERROR 1064 (42000) at line 1:` prefix mysql prints in batch mode). */
273	export function sanitizeError(message: string): string {
274	  return String(message ?? "")
275	    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\)\s+at line \d+:\s*/i, "")
276	    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\):\s*/i, "")
277	    .trim()
278	    .slice(0, 500) || "Query failed.";
279	}
280	
281	/** Row cap. We hard-limit rows so a caller that forgets a LIMIT still can't pull
282	 *  an unbounded set into memory/over the wire. */
283	export const MAX_ROWS = 1000;
284	
285	/** Sentinel a NULL cell resolves to (chosen so it can't collide with a real
286	 *  value; the UI renders it as a muted "NULL"). */
287	export const NULL_CELL = " NULL ";
288	
289	// ---- Safe SQL builders for the browse UI ------------------------------------
290	// The table name here is USER-CHOSEN. MySQL cannot bind an identifier as a
291	// prepared-statement parameter, so it only ever lands inside a backtick-quoted
292	// identifier in SQL that travels over the mysql2 wire (never a shell, never a
293	// CLI argv). We (1) accept only a conservative identifier charset, (2) double any
294	// backtick, and (3) the caller additionally checks membership against SHOW TABLES,
295	// so a value can neither break out of the quotes nor name a table the user can't
296	// see. LIMIT/OFFSET are integer-clamped and embedded as plain numbers.
297	
298	const TABLE_IDENT_RE = /^[A-Za-z0-9_$ .-]{1,64}$/;
299	export function isPlausibleTableName(name: string): boolean {
300	  return TABLE_IDENT_RE.test(String(name ?? ""));
301	}
302	
303	/** Quote an identifier for embedding between backticks (double internal ``` ` ```). */
304	export function quoteIdent(name: string): string {
305	  return "`" + String(name).replace(/`/g, "``") + "`";
306	}
307	
308	/** Page size for the row browser (rows per page). */
309	export const BROWSE_PAGE_SIZE = 50;
310	
311	export function showTablesSql(): string {
312	  return "SHOW TABLES;";
313	}
314	
315	/** All base tables in a database + their (approximate, storage-engine-reported)
316	 *  row counts, in ONE round-trip. The schema name is bound as a `?` param (never
317	 *  interpolated). `information_schema` rows are already filtered by MySQL to
318	 *  objects the connecting scoped user can see, so this can only reveal the
319	 *  account's own tables. Used to paint the sidebar tree with counts cheaply. */
320	export function tableCountsSql(): string {
321	  return "SELECT TABLE_NAME, TABLE_ROWS FROM information_schema.TABLES WHERE TABLE_SCHEMA = ? AND TABLE_TYPE = 'BASE TABLE' ORDER BY TABLE_NAME;";
322	}
323	
324	/** A bounded page of a table's rows. `offset`/`limit` are clamped to integers by
325	 *  the caller; embedded here as plain numbers (never strings). An optional ORDER
326	 *  BY column is backtick-quoted — the CALLER must have validated it by membership
327	 *  against the table's real columns first; `dir` is coerced to a literal keyword. */
328	export function browseTableSql(table: string, limit: number, offset: number, order?: { col: string; dir: "ASC" | "DESC" }): string {
329	  const lim = Math.max(1, Math.min(BROWSE_PAGE_SIZE, Math.floor(limit)));
330	  const off = Math.max(0, Math.floor(offset));
331	  const orderClause = order ? ` ORDER BY ${quoteIdent(order.col)} ${order.dir === "DESC" ? "DESC" : "ASC"}` : "";
332	  return `SELECT * FROM ${quoteIdent(table)}${orderClause} LIMIT ${lim} OFFSET ${off};`;
333	}
334	
335	export function countTableSql(table: string): string {
336	  return `SELECT COUNT(*) AS n FROM ${quoteIdent(table)};`;
337	}
338	
339	// ---- Structure + parameterized DML builders (for the row editor) ------------
340	// Every builder below quotes identifiers with `quoteIdent` (backtick-doubled) and
341	// leaves user VALUES as `?` placeholders, bound by mysql2 (escaped, never string-
342	// concatenated). Callers MUST validate the table by membership (SHOW TABLES) and
343	// each column name by membership (SHOW COLUMNS) before passing it in, so a name
344	// can only ever be one the scoped `_mgr` user is already allowed to see.
345	
346	export function showFullColumnsSql(table: string): string {
347	  return `SHOW FULL COLUMNS FROM ${quoteIdent(table)};`;
348	}
349	
350	export function showIndexSql(table: string): string {
351	  return `SHOW INDEX FROM ${quoteIdent(table)};`;
352	}
353	
354	export function showCreateTableSql(table: string): string {
355	  return `SHOW CREATE TABLE ${quoteIdent(table)};`;
356	}
357	
358	/** Bounded full-table SELECT for an export dump — capped at MAX_ROWS (the same
359	 *  row cap the transport enforces anyway), so an export can never pull an
360	 *  unbounded set. Rows beyond the cap are reported as truncated by the transport. */
361	export function dumpSelectSql(table: string): string {
362	  return `SELECT * FROM ${quoteIdent(table)} LIMIT ${MAX_ROWS};`;
363	}
364	
365	/** `INSERT INTO t (c1,c2) VALUES (?,?)` — the caller passes one param per column,
366	 *  in the same order as `cols`. `cols` must be validated column names. */
367	export function insertRowSql(table: string, cols: string[]): string {
368	  const idents = cols.map(quoteIdent).join(", ");
369	  const marks = cols.map(() => "?").join(", ");
370	  return `INSERT INTO ${quoteIdent(table)} (${idents}) VALUES (${marks});`;
371	}
372	
373	/** `UPDATE t SET c1=?,... WHERE w1<=>? AND ... LIMIT 1`. Params order is:
374	 *  [...set values, ...where values]. `<=>` is MySQL's NULL-safe equality so a row
375	 *  whose key column is NULL still matches. LIMIT 1 bounds a non-unique match. */
376	export function updateRowSql(table: string, setCols: string[], whereCols: string[]): string {
377	  const setClause = setCols.map((c) => `${quoteIdent(c)} = ?`).join(", ");
378	  const whereClause = whereCols.map((c) => `${quoteIdent(c)} <=> ?`).join(" AND ");
379	  return `UPDATE ${quoteIdent(table)} SET ${setClause} WHERE ${whereClause} LIMIT 1;`;
380	}
381	
382	/** `DELETE FROM t WHERE w1<=>? AND ... LIMIT 1`. Params: the where values. */
383	export function deleteRowSql(table: string, whereCols: string[]): string {
384	  const whereClause = whereCols.map((c) => `${quoteIdent(c)} <=> ?`).join(" AND ");
385	  return `DELETE FROM ${quoteIdent(table)} WHERE ${whereClause} LIMIT 1;`;
386	}
387	
388	/** Render one browse-grid cell as a SQL literal for an export dump. The NULL
389	 *  sentinel becomes the `NULL` keyword; every other value is escaped by the
390	 *  mysql2 string-escaper (single-quoted, backslash/quote-safe) — MySQL accepts a
391	 *  quoted string for numeric/date columns on import, so a per-type cast isn't
392	 *  needed for a faithful re-import. */
393	export function dumpValueLiteral(cell: string): string {
394	  if (cell === NULL_CELL) return "NULL";
395	  return sqlEscape(cell);
396	}
