1	"use server";
2	
3	// Proprietary in-portal DB manager — server actions.
4	//
5	// A Nxeon-built replacement for the Adminer file we used to drop into the
6	// customer's webroot. Everything here runs SERVER-SIDE: the customer never
7	// receives a DB credential, and every query is executed as the account's SCOPED
8	// MySQL manager user (see lib/hosting-db.ts + buildDbMgrGrantSql), which MySQL
9	// confines to this account's own `<username>_*` databases and nothing else.
10	//
11	// AUTH: every action requires the authenticated OWNER of the account (or an
12	// ADMIN). Actions that RUN SQL or reveal row data additionally call
13	// assertNotImpersonating — an admin impersonating a customer must not read or
14	// mutate that customer's live data (same discipline as revealHostingSftpPassword
15	// / createHostingDatabase). Read-only "which databases exist" listing (from OUR
16	// portal tables, not the node) is owner-or-admin without that extra bar.
17	
18	import { randomBytes } from "node:crypto";
19	import { revalidatePath } from "next/cache";
20	import { db } from "./db";
21	import { requireUser, assertNotImpersonating } from "./auth";
22	import { SANDBOX } from "./sandbox";
23	import { encryptSecret } from "./crypto-box";
24	import { checkRateLimit } from "./rate-limit";
25	import { isValidUnixUsername, isValidDbIdentifier, dbMgrUserFor } from "./hosting";
26	import {
27	  dbTargetFor,
28	  runScopedSql,
29	  showTablesSql,
30	  browseTableSql,
31	  countTableSql,
32	  tableCountsSql,
33	  showFullColumnsSql,
34	  showIndexSql,
35	  showCreateTableSql,
36	  dumpSelectSql,
37	  insertRowSql,
38	  updateRowSql,
39	  deleteRowSql,
40	  dumpValueLiteral,
41	  quoteIdent,
42	  isPlausibleTableName,
43	  MAX_SQL_BYTES,
44	  BROWSE_PAGE_SIZE,
45	  type QueryResult,
46	  type DbNodeTarget,
47	} from "./hosting-db";
48	
49	export type DbMgrStatus = { ready: boolean; provisioning: boolean; enabled: boolean };
50	export type DbMgrDatabase = { name: string; status: string };
51	export type DbMgrResult = {
52	  columns: string[];
53	  rows: string[][];
54	  truncated: boolean;
55	  error: string | null;
56	  elapsedMs: number;
57	  /** For non-SELECT statements (empty result set) — a friendly "OK" note. */
58	  ok?: boolean;
59	};
60	
61	export type DbMgrColumn = {
62	  name: string;
63	  type: string;
64	  nullable: boolean;
65	  key: string;      // "PRI" | "UNI" | "MUL" | ""
66	  default: string | null;
67	  extra: string;    // e.g. "auto_increment"
68	  comment: string;
69	};
70	export type DbMgrIndex = { name: string; columns: string[]; unique: boolean };
71	export type DbMgrStructure = {
72	  columns: DbMgrColumn[];
73	  indexes: DbMgrIndex[];
74	  /** Column names of the PRIMARY KEY (empty when the table has none). */
75	  primaryKey: string[];
76	};
77	/** A value the row editor sends us: a string, or null for SQL NULL. */
78	export type DbCellValue = string | null;
79	
80	/** Owner-or-admin account load with the node relation + manager fields. */
81	async function loadOwned(accountId: string) {
82	  const user = await requireUser();
83	  const a = await db.hostingAccount.findUnique({
84	    where: { id: accountId },
85	    include: { node: { select: { sshHost: true, sshPort: true, rootPasswordEnc: true } } },
86	  });
87	  if (!a) return { error: "Account not found." as const };
88	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
89	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
90	  return { user, a };
