105	/**
106	 * Make sure the account has a provisioned DB-manager user. Idempotent:
107	 *   - already ready → { ready:true }
108	 *   - has creds but no ACTIVE user yet (or first call) → generate creds if
109	 *     missing, queue ENSURE_DBMGR, report { provisioning:true }
110	 * Owner-or-admin + not-impersonating (this mints a live DB credential on the box).
111	 * SANDBOX: mark ready immediately (no real node).
112	 */
113	export async function ensureDbManager(accountId: string): Promise<DbMgrStatus & { error?: string }> {
114	  const ctx = await loadOwned(accountId);
115	  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
116	  await assertNotImpersonating();
117	  const { a } = ctx;
118	  if (!isValidUnixUsername(a.username)) return { ready: false, provisioning: false, enabled: false, error: "Account not ready." };
119	
120	  if (SANDBOX) {
121	    if (!a.dbMgrReady) {
122	      await db.hostingAccount.update({
123	        where: { id: a.id },
124	        data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: true },
125	      });
126	    }
127	    return { ready: true, provisioning: false, enabled: true };
128	  }
129	
130	  if (a.dbMgrReady && a.dbMgrUser && a.dbMgrPassEnc) return { ready: true, provisioning: false, enabled: true };
131	
132	  // Generate + persist the manager credential once (encrypted at rest); the
133	  // worker applies it on the node. Keep the same password across re-queues so the
134	  // stored cred always matches what the node was told.
135	  if (!a.dbMgrUser || !a.dbMgrPassEnc) {
136	    await db.hostingAccount.update({
137	      where: { id: a.id },
138	      data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: false },
139	    });
140	  }
141	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } });
142	  if (!inFlight) await db.hostingTask.create({ data: { accountId, kind: "ENSURE_DBMGR" } });
143	  revalidatePath(`/dashboard/hosting/${accountId}`);
144	  return { ready: false, provisioning: true, enabled: true };
145	}
