194	  await assertNotImpersonating();
195	  const { user } = ctx;
196	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
197	  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
198	  if (SANDBOX) return { tables: SANDBOX_TABLES };
199	  const target = dbTargetFor(ctx.a);
200	  if (!target) return { error: "The database manager is still being prepared." };
201	  const res = await runScopedSql(target, dbName, showTablesSql());
