206	/** Browse a page of a table's rows. Validates the table by MEMBERSHIP against the
207	 *  db's real table list (so a user can't name a table they can't see), then runs
208	 *  a bounded SELECT + a COUNT. Owner-or-admin + not-impersonating. */
209	export async function dbmgrBrowseTable(
210	  accountId: string,
211	  dbName: string,
212	  table: string,
213	  page: number,
214	  sortColumn?: string,
215	  sortDir?: "ASC" | "DESC",
216	): Promise<{ error?: string; columns?: string[]; rows?: string[][]; total?: number | null; page?: number; pageSize?: number; truncated?: boolean; sortColumn?: string | null; sortDir?: "ASC" | "DESC" }> {
217	  const ctx = await loadOwned(accountId);
218	  if ("error" in ctx) return { error: ctx.error };
219	  await assertNotImpersonating();
220	  const { user } = ctx;
221	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
222	  if (!isPlausibleTableName(table)) return { error: "Invalid table name." };
223	  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
224	  const p = Math.max(0, Math.floor(Number(page) || 0));
225	  const dir: "ASC" | "DESC" = sortDir === "DESC" ? "DESC" : "ASC";
226	
227	  if (SANDBOX) {
228	    const demo = sandboxResult("select");
229	    return { columns: demo.columns, rows: demo.rows, total: demo.rows.length, page: p, pageSize: BROWSE_PAGE_SIZE, truncated: false, sortColumn: sortColumn ?? null, sortDir: dir };
230	  }
231	  const target = dbTargetFor(ctx.a);
232	  if (!target) return { error: "The database manager is still being prepared." };
233	
234	  // Membership check: the table MUST be one the scoped user can actually see.
235	  const listed = await runScopedSql(target, dbName, showTablesSql());
236	  if (listed.error) return { error: listed.error };
237	  const tables = listed.rows.map((r) => r[0]);
238	  if (!tables.includes(table)) return { error: "Unknown table." };
239	
240	  // A sort column, if given, is validated by MEMBERSHIP against the table's real
241	  // columns before it can be backtick-quoted into ORDER BY (never interpolated raw).
242	  let order: { col: string; dir: "ASC" | "DESC" } | undefined;
243	  if (sortColumn && isPlausibleTableName(sortColumn)) {
244	    const colsRes = await runScopedSql(target, dbName, showFullColumnsSql(table));
245	    if (!colsRes.error && colsRes.rows.map((r) => r[0]).includes(sortColumn)) {
246	      order = { col: sortColumn, dir };
247	    }
248	  }
249	
250	  const res = await runScopedSql(target, dbName, browseTableSql(table, BROWSE_PAGE_SIZE, p * BROWSE_PAGE_SIZE, order));
251	  if (res.error) return { error: res.error };
252	  const countRes = await runScopedSql(target, dbName, countTableSql(table));
253	  const total = countRes.error ? null : Number(countRes.rows[0]?.[0] ?? "0");
254	  return { columns: res.columns, rows: res.rows, total: Number.isFinite(total as number) ? (total as number) : null, page: p, pageSize: BROWSE_PAGE_SIZE, truncated: res.truncated, sortColumn: order?.col ?? null, sortDir: dir };
255	}
