257	/**
258	 * Run arbitrary SQL scoped to one of the account's databases. The SQL runs through
259	 * the mysql2 protocol driver over an SSH-forwarded channel to the node's localhost
260	 * MySQL (never a `mysql` CLI, never a shell), executed as the scoped manager user —
261	 * MySQL's grant is the hard isolation boundary, and there is no CLI meta-command
262	 * interpreter to abuse. Owner-or-admin + not-impersonating + rate-limited.
263	 */
264	export async function dbmgrRunSql(accountId: string, dbName: string, sql: string): Promise<DbMgrResult> {
265	  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
266	  const ctx = await loadOwned(accountId);
267	  if ("error" in ctx) return { ...empty, error: ctx.error ?? null };
268	  await assertNotImpersonating();
269	  const { user } = ctx;
270	  if (!(await assertOwnedDatabase(accountId, dbName))) return { ...empty, error: "Unknown database." };
271	  const text = String(sql ?? "").trim();
272	  if (!text) return { ...empty, error: "Enter a SQL statement." };
273	  if (Buffer.byteLength(text, "utf8") > MAX_SQL_BYTES) return { ...empty, error: "That query is too large." };
274	  if (!rlOk(user.id, accountId)) return { ...empty, error: "Too many requests — slow down a moment." };
275	
276	  if (SANDBOX) return sandboxResult(text);
277	  const target = dbTargetFor(ctx.a);
278	  if (!target) return { ...empty, error: "The database manager is still being prepared." };
279	  const res: QueryResult = await runScopedSql(target, dbName, text);
280	  if (res.error) return { ...res, error: res.error };
281	  return { ...res, ok: res.columns.length === 0 };
282	}
