284	/* ─────────────────────── Structure + row editor (parameterized) ──────────────
285	 * These actions power the data-grid's insert / edit / delete and the "structure"
286	 * tab. They share the same isolation as the query surface: owner-or-admin, not
287	 * impersonating, owned db, rate-limited, and — crucially — every statement runs
288	 * through `runScopedSql` as the scoped `<username>_mgr` user over the SSH tunnel.
289	 * User VALUES are always bound as `?` parameters (never string-concatenated);
290	 * user IDENTIFIERS (table + column names) are validated by MEMBERSHIP against the
291	 * live table/column list before they can be backtick-quoted into SQL, so a name
292	 * can only ever be one the scoped user is already permitted to see. */
293	
294	const SANDBOX_STRUCTURE: DbMgrStructure = {
295	  columns: [
296	    { name: "id", type: "int(11)", nullable: false, key: "PRI", default: null, extra: "auto_increment", comment: "" },
297	    { name: "name", type: "varchar(255)", nullable: false, key: "", default: null, extra: "", comment: "" },
298	    { name: "created_at", type: "datetime", nullable: true, key: "", default: "CURRENT_TIMESTAMP", extra: "", comment: "" },
299	  ],
300	  indexes: [{ name: "PRIMARY", columns: ["id"], unique: true }],
301	  primaryKey: ["id"],
302	};
