304	/** Owner-or-admin + not-impersonating + owned-db + rate-limit + ready-target
305	 *  preamble shared by the live-data actions. Returns a discriminated result. */
306	async function liveTarget(
307	  accountId: string,
308	  dbName: string,
309	): Promise<{ error: string } | { mode: "sandbox" } | { mode: "live"; target: DbNodeTarget }> {
310	  const ctx = await loadOwned(accountId);
311	  if ("error" in ctx) return { error: ctx.error ?? "Request failed." };
312	  await assertNotImpersonating();
313	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
314	  if (!rlOk(ctx.user.id, accountId)) return { error: "Too many requests — slow down a moment." };
315	  if (SANDBOX) return { mode: "sandbox" };
316	  const target = dbTargetFor(ctx.a);
317	  if (!target) return { error: "The database manager is still being prepared." };
318	  return { mode: "live", target };
319	}
