321	/** Confirm `table` is one the scoped user can actually see (membership check via
322	 *  SHOW TABLES). The lone hard identifier boundary for the DML/structure paths. */
323	async function tableIsVisible(target: DbNodeTarget, dbName: string, table: string): Promise<{ error: string } | { ok: true }> {
324	  if (!isPlausibleTableName(table)) return { error: "Invalid table name." };
325	  const listed = await runScopedSql(target, dbName, showTablesSql());
326	  if (listed.error) return { error: listed.error };
327	  if (!listed.rows.map((r) => r[0]).includes(table)) return { error: "Unknown table." };
328	  return { ok: true };
