331	/** Fetch a table's structure (columns, indexes, primary key) as the scoped user.
332	 *  Assumes membership has already been asserted for `table`. */
333	async function fetchStructure(target: DbNodeTarget, dbName: string, table: string): Promise<{ error: string } | { structure: DbMgrStructure }> {
334	  const cols = await runScopedSql(target, dbName, showFullColumnsSql(table));
335	  if (cols.error) return { error: cols.error };
336	  // SHOW FULL COLUMNS positional order: Field, Type, Collation, Null, Key, Default, Extra, Privileges, Comment.
337	  const columns: DbMgrColumn[] = cols.rows.map((r) => ({
338	    name: r[0],
339	    type: r[1],
340	    nullable: (r[3] ?? "").toUpperCase() === "YES",
341	    key: r[4] ?? "",
342	    default: r[5] === NULL_SENTINEL ? null : (r[5] ?? null),
343	    extra: r[6] ?? "",
344	    comment: r[8] ?? "",
345	  }));
346	
347	  const idx = await runScopedSql(target, dbName, showIndexSql(table));
348	  // SHOW INDEX positional: Table, Non_unique, Key_name, Seq_in_index, Column_name, ...
349	  const byName = new Map<string, { name: string; unique: boolean; cols: Array<{ seq: number; col: string }> }>();
350	  if (!idx.error) {
351	    for (const r of idx.rows) {
352	      const keyName = r[2];
353	      const nonUnique = r[1] === "1";
354	      const seq = Number(r[3] ?? "0") || 0;
355	      const col = r[4];
356	      const entry = byName.get(keyName) ?? { name: keyName, unique: !nonUnique, cols: [] };
357	      entry.cols.push({ seq, col });
358	      byName.set(keyName, entry);
359	    }
360	  }
361	  const indexes: DbMgrIndex[] = [...byName.values()].map((e) => ({
362	    name: e.name,
363	    unique: e.unique,
364	    columns: e.cols.sort((a, b) => a.seq - b.seq).map((c) => c.col),
365	  }));
366	  const primaryKey = indexes.find((i) => i.name === "PRIMARY")?.columns
367	    ?? columns.filter((c) => c.key === "PRI").map((c) => c.name);
368	
369	  return { structure: { columns, indexes, primaryKey } };
370	}
