412	/** INSERT a row. `values` is column→value (null = SQL NULL); unknown columns are
413	 *  dropped, values are bound as `?` params. Owner-or-admin + not-impersonating. */
414	export async function dbmgrInsertRow(accountId: string, dbName: string, table: string, values: Record<string, DbCellValue>): Promise<DbMgrResult> {
415	  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
416	  const lt = await liveTarget(accountId, dbName);
417	  if ("error" in lt) return { ...empty, error: lt.error };
418	  if (lt.mode === "sandbox") return { ...empty, ok: true };
419	  const vis = await tableIsVisible(lt.target, dbName, table);
420	  if ("error" in vis) return { ...empty, error: vis.error };
421	  const s = await fetchStructure(lt.target, dbName, table);
422	  if ("error" in s) return { ...empty, error: s.error };
423	
424	  const real = new Set(s.structure.columns.map((c) => c.name));
425	  const cols = keepValidColumns(Object.keys(values ?? {}), real);
426	  if (cols.length === 0) return { ...empty, error: "Provide at least one column value." };
427	  const params = cols.map((c) => values[c]);
428	  const res = await runScopedSql(lt.target, dbName, insertRowSql(table, cols), params);
429	  if (res.error) return { ...res, error: res.error };
430	  return { ...res, ok: true };
431	}
