433	/** Resolve the WHERE columns that identify an existing row: prefer the PRIMARY
434	 *  KEY (when every PK column is present in `where`), else fall back to every
435	 *  supplied real column. Returns [] when the row can't be safely identified. */
436	function whereColumnsFor(where: Record<string, DbCellValue>, structure: DbMgrStructure, real: Set<string>): string[] {
437	  const supplied = keepValidColumns(Object.keys(where ?? {}), real);
438	  const pk = structure.primaryKey;
439	  if (pk.length > 0 && pk.every((c) => c in (where ?? {}))) return pk;
440	  return supplied;
441	}
