443	/** UPDATE one row. `where` identifies the row (original values); `changes` are the
444	 *  new column→value pairs. Both bound as `?` params, LIMIT 1 on the write. */
445	export async function dbmgrUpdateRow(
446	  accountId: string,
447	  dbName: string,
448	  table: string,
449	  where: Record<string, DbCellValue>,
450	  changes: Record<string, DbCellValue>,
451	): Promise<DbMgrResult> {
452	  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
453	  const lt = await liveTarget(accountId, dbName);
454	  if ("error" in lt) return { ...empty, error: lt.error };
455	  if (lt.mode === "sandbox") return { ...empty, ok: true };
456	  const vis = await tableIsVisible(lt.target, dbName, table);
457	  if ("error" in vis) return { ...empty, error: vis.error };
458	  const s = await fetchStructure(lt.target, dbName, table);
459	  if ("error" in s) return { ...empty, error: s.error };
460	
461	  const real = new Set(s.structure.columns.map((c) => c.name));
462	  const setCols = keepValidColumns(Object.keys(changes ?? {}), real);
463	  if (setCols.length === 0) return { ...empty, error: "No changes to save." };
