493	/** Build a downloadable SQL dump of a single table (CREATE TABLE + a bounded set
494	 *  of INSERTs) via the scoped connection — no root, no mysqldump. Values are
495	 *  escaped by the mysql2 string-escaper. Bounded by the transport's row cap.
496	 *  Owner-or-admin + not-impersonating. */
497	export async function dbmgrExportTable(accountId: string, dbName: string, table: string): Promise<{ error?: string; filename?: string; sql?: string; truncated?: boolean }> {
498	  const lt = await liveTarget(accountId, dbName);
499	  if ("error" in lt) return { error: lt.error };
500	  if (lt.mode === "sandbox") {
501	    return { filename: `${table}.sql`, sql: `-- Nxeon DB Studio (sandbox) export of \`${table}\`\n`, truncated: false };
502	  }
503	  const vis = await tableIsVisible(lt.target, dbName, table);
504	  if ("error" in vis) return { error: vis.error };
505	
506	  const create = await runScopedSql(lt.target, dbName, showCreateTableSql(table));
507	  if (create.error) return { error: create.error };
508	  // SHOW CREATE TABLE returns one row: [Table, "Create Table"].
509	  const createStmt = create.rows[0]?.[1] ?? "";
510	
511	  const s = await fetchStructure(lt.target, dbName, table);
512	  if ("error" in s) return { error: s.error };
513	  const colNames = s.structure.columns.map((c) => c.name);
514	
515	  const data = await runScopedSql(lt.target, dbName, dumpSelectSql(table));
516	  if (data.error) return { error: data.error };
517	
518	  const lines: string[] = [];
519	  lines.push(`-- Nxeon DB Studio export`);
520	  lines.push(`-- database: ${dbName}`);
521	  lines.push(`-- table:    ${table}`);
522	  lines.push(`-- generated: ${new Date().toISOString()}`);
523	  lines.push(`-- rows:     ${data.rows.length}${data.truncated ? ` (truncated at ${data.rows.length})` : ""}`);
524	  lines.push("");
525	  lines.push("SET FOREIGN_KEY_CHECKS=0;");
526	  lines.push(`DROP TABLE IF EXISTS ${quoteIdent(table)};`);
527	  lines.push(`${createStmt};`);
528	  lines.push("");
529	  if (data.rows.length > 0) {
530	    const colList = colNames.map((c) => quoteIdent(c)).join(", ");
531	    for (const row of data.rows) {
532	      const vals = row.map((cell) => dumpValueLiteral(cell)).join(", ");
533	      lines.push(`INSERT INTO ${quoteIdent(table)} (${colList}) VALUES (${vals});`);
534	    }
535	  }
536	  lines.push("");
537	  lines.push("SET FOREIGN_KEY_CHECKS=1;");
538	  return { filename: `${table}.sql`, sql: lines.join("\n"), truncated: data.truncated };
539	}
