271	
272	  // Structure powers the row editor (columns, PK). Loaded once per table.
273	  const [structure, setStructure] = useState<DbMgrStructure | null>(null);
274	  useEffect(() => {
275	    let cancelled = false;
276	    dbmgrTableStructure(accountId, dbName, table).then((r) => { if (!cancelled && r.structure) setStructure(r.structure); });
277	    return () => { cancelled = true; };
278	  }, [accountId, dbName, table]);
279	
280	  // Row-editor modal state.
281	  const [editor, setEditor] = useState<{ mode: "insert" | "edit"; original: Record<string, DbCellValue> | null } | null>(null);
282	  const [confirmDel, setConfirmDel] = useState<{ row: Record<string, DbCellValue>; label: string } | null>(null);
283	  const [busyMsg, setBusyMsg] = useState("");
284	
285	  useEffect(() => {
286	    let cancelled = false;
287	    setBusy(true); setErr("");
288	    dbmgrBrowseTable(accountId, dbName, table, page, sort?.col, sort?.dir).then((res) => {
289	      if (cancelled) return;
290	      setBusy(false);
291	      if (res.error) { setErr(res.error); setData(null); return; }
292	      setData({ columns: res.columns ?? [], rows: res.rows ?? [], total: res.total ?? null, pageSize: res.pageSize ?? 50, truncated: !!res.truncated });
293	    });
294	    return () => { cancelled = true; };
295	  }, [accountId, dbName, table, page, sort, reload]);
296	
297	  const total = data?.total ?? null;
298	  const pageSize = data?.pageSize ?? 50;
299	  const maxPage = total != null ? Math.max(0, Math.ceil(total / pageSize) - 1) : (data && data.rows.length === pageSize ? page + 1 : page);
300	  const from = data && data.rows.length ? page * pageSize + 1 : 0;
301	  const to = data ? page * pageSize + data.rows.length : 0;
302	
303	  function toggleSort(col: string) {
304	    setPage(0);
