326	  async function exportDump() {
327	    setBusyMsg("Building SQL dump…");
328	    const res = await dbmgrExportTable(accountId, dbName, table);
329	    setBusyMsg("");
330	    if (res.error) { setErr(res.error); return; }
331	    downloadText(res.filename ?? `${table}.sql`, res.sql ?? "");
332	  }
333	
334	  return (
335	    <div>
336	      {/* Toolbar */}
337	      <div className="mb-2 flex flex-wrap items-center gap-2">
338	        <button className="btn-primary px-3 py-1.5 text-xs" disabled={!structure} onClick={() => setEditor({ mode: "insert", original: null })}><PlusIcon className="h-3.5 w-3.5" /> Insert row</button>
