557	type FieldState = { value: string; isNull: boolean; include: boolean };
558	
559	function RowEditor({
560	  mode,
561	  table,
562	  structure,
563	  original,
564	  onClose,
565	  onSave,
566	}: {
567	  mode: "insert" | "edit";
568	  table: string;
569	  structure: DbMgrStructure;
570	  original: Record<string, DbCellValue> | null;
571	  onClose: () => void;
572	  onSave: (payload: { values: Record<string, DbCellValue>; changes: Record<string, DbCellValue> }) => Promise<string | null>;
573	}) {
574	  const [fields, setFields] = useState<Record<string, FieldState>>(() => {
575	    const init: Record<string, FieldState> = {};
576	    for (const c of structure.columns) {
577	      if (mode === "edit" && original) {
578	        const v = original[c.name];
579	        init[c.name] = { value: v === null ? "" : (v ?? ""), isNull: v === null, include: true };
580	      } else {
581	        // Insert: pre-omit auto_increment / defaulted columns so the DB fills them.
582	        const auto = /auto_increment/i.test(c.extra) || c.default !== null;
583	        init[c.name] = { value: "", isNull: false, include: !auto };
584	      }
585	    }
586	    return init;
587	  });
588	  const [err, setErr] = useState("");
589	  const [busy, setBusy] = useState(false);
590	
591	  function set(name: string, patch: Partial<FieldState>) {
592	    setFields((f) => ({ ...f, [name]: { ...f[name], ...patch } }));
593	  }
594	
595	  async function submit() {
596	    setBusy(true); setErr("");
597	    const values: Record<string, DbCellValue> = {};
598	    const changes: Record<string, DbCellValue> = {};
599	    for (const c of structure.columns) {
600	      const f = fields[c.name];
601	      const val: DbCellValue = f.isNull ? null : f.value;
602	      if (mode === "insert") {
603	        if (f.include) values[c.name] = val;
604	      } else {
605	        const orig = original ? original[c.name] ?? null : null;
606	        const origNorm = orig === null ? null : String(orig);
607	        const nextNorm = f.isNull ? null : f.value;
608	        if (origNorm !== nextNorm) changes[c.name] = val;
609	      }
610	    }
611	    if (mode === "edit" && Object.keys(changes).length === 0) { setBusy(false); setErr("No changes to save."); return; }
612	    if (mode === "insert" && Object.keys(values).length === 0) { setBusy(false); setErr("Set at least one column."); return; }
613	    const e = await onSave({ values, changes });
614	    setBusy(false);
615	    if (e) setErr(e);
616	  }
617	
618	  return (
619	    <Modal onClose={onClose} title={mode === "insert" ? `Insert row into ${table}` : `Edit row in ${table}`} wide>
620	      <div className="max-h-[60vh] space-y-2.5 overflow-y-auto pr-1">
621	        {structure.columns.map((c) => {
622	          const f = fields[c.name];
623	          return (
624	            <div key={c.name} className="grid grid-cols-[10rem_1fr] items-start gap-3">
625	              <div className="pt-2">
626	                <p className="flex items-center gap-1.5 font-mono text-xs text-slate-200">
627	                  {c.key === "PRI" && <KeyIcon className="h-3 w-3 text-amber-300" />}{c.name}
628	                </p>
629	                <p className="mt-0.5 font-mono text-[10px] text-slate-500">{c.type}{/auto_increment/i.test(c.extra) ? " · auto" : ""}{!c.nullable ? " · not null" : ""}</p>
630	              </div>
631	              <div className="min-w-0">
632	                <div className="flex items-center gap-2">
633	                  {isTextarea(c) ? (
634	                    <textarea className="input h-20 font-mono text-xs disabled:opacity-40" disabled={f.isNull} value={f.value} onChange={(e) => set(c.name, { value: e.target.value, include: true })} />
635	                  ) : (
636	                    <input className="input py-2 font-mono text-xs disabled:opacity-40" disabled={f.isNull} value={f.value} placeholder={mode === "insert" && !f.include ? "(default)" : ""} onChange={(e) => set(c.name, { value: e.target.value, include: true })} />
637	                  )}
638	                  {c.nullable && (
639	                    <label className="flex shrink-0 cursor-pointer items-center gap-1 text-[11px] text-slate-400">
640	                      <input type="checkbox" checked={f.isNull} onChange={(e) => set(c.name, { isNull: e.target.checked, include: true })} className="accent-brand-500" /> NULL
641	                    </label>
642	                  )}
643	                </div>
644	              </div>
645	            </div>
646	          );
647	        })}
648	      </div>
649	      {err && <p className="mt-3 whitespace-pre-wrap rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 font-mono text-[11px] text-red-200">{err}</p>}
650	      <div className="mt-4 flex items-center justify-end gap-2">
651	        <button className="btn-ghost px-3 py-2 text-xs" onClick={onClose} disabled={busy}>Cancel</button>
652	        <button className="btn-primary px-4 py-2 text-xs" onClick={submit} disabled={busy}>{busy ? "Saving…" : mode === "insert" ? "Insert row" : "Save changes"}</button>
653	      </div>
654	    </Modal>
655	  );
656	}
