658	/* ================================================================ SqlEditor === */
659	
660	const DESTRUCTIVE_RE = /^\s*(drop|truncate|delete|alter|update|replace|grant|revoke|create)\b/i;
661	
662	function SqlEditor({ accountId, dbName, onChanged }: { accountId: string; dbName: string; onChanged: () => void }) {
663	  const [sql, setSql] = useState("");
664	  const [busy, setBusy] = useState(false);
665	  const [err, setErr] = useState("");
666	  const [note, setNote] = useState("");
667	  const [result, setResult] = useState<{ columns: string[]; rows: string[][]; truncated: boolean } | null>(null);
668	  const [pendingConfirm, setPendingConfirm] = useState(false);
669	
670	  async function execute() {
671	    setBusy(true); setErr(""); setNote(""); setResult(null); setPendingConfirm(false);
672	    const res = await dbmgrRunSql(accountId, dbName, sql);
673	    setBusy(false);
674	    if (res.error) { setErr(res.error); return; }
675	    if (res.columns.length === 0) {
676	      setNote(`Statement executed successfully · ${res.elapsedMs} ms`);
677	      onChanged();
678	      return;
679	    }
680	    setResult({ columns: res.columns, rows: res.rows, truncated: res.truncated });
681	    setNote(`${res.rows.length} row${res.rows.length === 1 ? "" : "s"}${res.truncated ? "+" : ""} · ${res.elapsedMs} ms`);
682	  }
683	
684	  function run() {
685	    if (!sql.trim()) return;
686	    if (DESTRUCTIVE_RE.test(sql)) { setPendingConfirm(true); return; }
687	    execute();
688	  }
689	
690	  return (
691	    <div>
692	      <div className="mb-2 flex items-center gap-2 text-[11px] text-slate-500">
693	        <SqlIcon className="h-3.5 w-3.5 text-brand-300" />
694	        Running against <span className="font-mono text-slate-300">{dbName}</span> as your scoped database user — queries can only ever touch your own databases.
695	      </div>
696	      <div className="overflow-hidden rounded-xl border border-white/[0.08] focus-within:border-brand-400/50 focus-within:ring-2 focus-within:ring-brand-500/20">
697	        <textarea
698	          className="block h-36 w-full resize-y bg-navy-900/80 px-3.5 py-3 font-mono text-xs text-slate-100 outline-none placeholder:text-slate-600"
699	          placeholder="SELECT * FROM your_table LIMIT 20;"
700	          spellCheck={false}
701	          value={sql}
702	          onChange={(e) => setSql(e.target.value)}
703	          onKeyDown={(e) => { if ((e.metaKey || e.ctrlKey) && e.key === "Enter") run(); }}
704	        />
705	      </div>
706	      <div className="mt-2 flex flex-wrap items-center gap-2">
707	        <button className="btn-primary px-4 py-1.5 text-xs" disabled={busy || !sql.trim()} onClick={run}><PlayIcon className="h-3.5 w-3.5" />{busy ? "Running…" : "Run"}</button>
708	        <span className="kbd">⌘/Ctrl + Enter</span>
709	        <button className="btn-ghost px-2 py-1.5 text-xs" disabled={busy || !sql} onClick={() => { setSql(""); setResult(null); setNote(""); setErr(""); }}>Clear</button>
710	        {note && <span className="ml-auto text-[11px] text-slate-400">{note}</span>}
711	      </div>
712	
713	      {err && <div className="mt-3"><ErrorBanner msg={err} onClose={() => setErr("")} /></div>}
714	      {result && (
715	        <div className="mt-3">
716	          <ResultGrid columns={result.columns} rows={result.rows} truncated={result.truncated} />
717	        </div>
718	      )}
719	
720	      {pendingConfirm && (
721	        <ConfirmDialog
722	          title="Run this statement?"
723	          body={<>This looks like it modifies data or schema. It runs as your scoped database user, but the change may be hard to undo. Continue?</>}
724	          confirmLabel="Run statement"
725	          danger
726	          onCancel={() => setPendingConfirm(false)}
727	          onConfirm={execute}
728	        />
729	      )}
730	    </div>
731	  );
732	}
733	
734	function ResultGrid({ columns, rows, truncated }: { columns: string[]; rows: string[][]; truncated: boolean }) {
735	  if (columns.length === 0) return <p className="text-xs text-slate-500">No columns.</p>;
736	  return (
737	    <div>
738	      <div className="overflow-x-auto rounded-xl border border-white/[0.06]">
739	        <table className="min-w-full text-left text-xs">
740	          <thead className="bg-white/[0.03]">
741	            <tr>{columns.map((c, i) => <th key={i} className="whitespace-nowrap border-b border-white/[0.06] px-3 py-2 font-semibold text-slate-300">{c}</th>)}</tr>
