749	                    {r[ci] === NULL_CELL ? <span className="italic text-slate-600">NULL</span> : cell(r[ci])}
750	                  </td>
751	                ))}
752	              </tr>
753	            ))}
754	          </tbody>
755	        </table>
756	      </div>
757	      {truncated && <p className="mt-1.5 text-[11px] text-amber-300">Results truncated — refine with a tighter LIMIT or WHERE to see more.</p>}
758	    </div>
759	  );
