export function browseTableSql(table: string, limit: number, offset: number, order?: { col: string; dir: "ASC" | "DESC" }): string {
  const lim = clampPageSize(limit);
  const off = Math.max(0, Math.floor(offset));
  const orderClause = order ? ` ORDER BY ${quoteIdent(order.col)} ${order.dir === "DESC" ? "DESC" : "ASC"}` : "";
  return `SELECT * FROM ${quoteIdent(table)}${orderClause} LIMIT ${lim} OFFSET ${off};`;
}

/** Clamp a requested page size to [1, MAX_BROWSE_PAGE_SIZE] (integer). */
export function clampPageSize(n: number): number {
  return Math.max(1, Math.min(MAX_BROWSE_PAGE_SIZE, Math.floor(Number(n) || BROWSE_PAGE_SIZE)));
}

/** Build the WHERE fragment (sans the `WHERE` keyword) for the browse grid's
 *  filtering: per-column LIKE filters (ANDed) plus an optional global search
 *  term ORed across the given text columns. Every column name MUST have been
 *  validated by MEMBERSHIP against the table's real columns before it reaches
 *  here; values are NEVER embedded — they are returned as `?` placeholders and
 *  bound by the caller in exactly this order:
 *    [...one value per filterCol, ...one search term per searchCol].
 *  Returns { clause } where clause is "" when there is nothing to filter. */
export function browseWhereClause(filterCols: string[], searchCols: string[]): { clause: string } {
  const parts: string[] = [];
  for (const c of filterCols) parts.push(`${quoteIdent(c)} LIKE ?`);
  if (searchCols.length > 0) {
    parts.push(`(${searchCols.map((c) => `${quoteIdent(c)} LIKE ?`).join(" OR ")})`);
  }
  return { clause: parts.length ? ` WHERE ${parts.join(" AND ")}` : "" };
}

/** A filtered page of rows. Same guarantees as browseTableSql; the WHERE comes
 *  from browseWhereClause (validated identifiers, `?`-bound values). */
export function filteredBrowseSql(
  table: string,
  filterCols: string[],
  searchCols: string[],
  limit: number,
  offset: number,
  order?: { col: string; dir: "ASC" | "DESC" },
): string {
  const lim = clampPageSize(limit);
  const off = Math.max(0, Math.floor(offset));
  const { clause } = browseWhereClause(filterCols, searchCols);
  const orderClause = order ? ` ORDER BY ${quoteIdent(order.col)} ${order.dir === "DESC" ? "DESC" : "ASC"}` : "";
  return `SELECT * FROM ${quoteIdent(table)}${clause}${orderClause} LIMIT ${lim} OFFSET ${off};`;
}

export function countTableSql(table: string): string {
  return `SELECT COUNT(*) AS n FROM ${quoteIdent(table)};`;
}

/** COUNT(*) with the same filter WHERE as filteredBrowseSql (for the total). */
export function countFilteredSql(table: string, filterCols: string[], searchCols: string[]): string {
  const { clause } = browseWhereClause(filterCols, searchCols);
  return `SELECT COUNT(*) AS n FROM ${quoteIdent(table)}${clause};`;
}

