/** Render one browse-grid cell as a SQL literal for an export dump. The NULL
 *  sentinel becomes the `NULL` keyword; every other value is escaped by the
 *  mysql2 string-escaper (single-quoted, backslash/quote-safe) — MySQL accepts a
 *  quoted string for numeric/date columns on import, so a per-type cast isn't
 *  needed for a faithful re-import. */
export function dumpValueLiteral(cell: string): string {
  if (cell === NULL_CELL) return "NULL";
  return sqlEscape(cell);
}

/** Render one browse-grid cell for a CSV export. NULL becomes an empty field;
 *  everything else is RFC-4180 quoted (double any internal quote, wrap in quotes
 *  when it contains a comma / quote / newline). Pure string transform — no SQL. */
export function csvCell(cell: string): string {
  if (cell === NULL_CELL) return "";
  const s = String(cell);
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

/** Build a CSV document from a browse result (header row + data rows). */
export function toCsv(columns: string[], rows: string[][]): string {
  const head = columns.map((c) => csvCell(c)).join(",");
  const body = rows.map((r) => r.map((v) => csvCell(v)).join(",")).join("\r\n");
  return rows.length ? `${head}\r\n${body}\r\n` : `${head}\r\n`;
}

// ---- Database-overview builder ----------------------------------------------
// One round-trip that paints the "no table selected" overview: every base table
// with its approximate row count, data/index size, engine and collation. The
// schema is bound as a `?` param (never interpolated); information_schema rows
// are already filtered by MySQL to objects the scoped user can see.

export function overviewSql(): string {
  return (
    "SELECT TABLE_NAME, TABLE_ROWS, DATA_LENGTH, INDEX_LENGTH, ENGINE, TABLE_COLLATION " +
    "FROM information_schema.TABLES " +
    "WHERE TABLE_SCHEMA = ? AND TABLE_TYPE = 'BASE TABLE' " +
    "ORDER BY TABLE_NAME;"
  );
}

// ---- Structure / DDL builders -----------------------------------------------
// DDL cannot use `?` placeholders for identifiers OR for the column type, so
// everything embedded here MUST be pre-validated by the caller:
//   * table / column / index names → membership check (SHOW TABLES / SHOW COLUMNS)
//     or isSimpleIdent for a NEW name, then quoteIdent (backtick-doubled).
//   * a NEW column's type → isValidColumnType (strict allow-list of base types +
//     an optional (n) / (n,m) length), then embedded verbatim.
// There are NO user VALUES in any DDL statement below (no DEFAULT expressions),
// so there is no value-injection surface; only pre-validated identifiers/types.

/** A strict identifier for a brand-new object name (column, index, renamed
 *  table): letters/digits/underscore only, 1-64 chars. Tighter than
 *  isPlausibleTableName (which tolerates existing names with spaces/dots). */
export function isSimpleIdent(name: string): boolean {
  return /^[A-Za-z0-9_]{1,64}$/.test(String(name ?? ""));
}

/** Allow-list of column base types the "add column" form accepts, with an
 *  optional length/precision. Anything else is rejected before it can be
 *  embedded in DDL. Case-insensitive; returns the normalised (upper-cased base,
 *  original digits) type, or null when invalid. */
export function normalizeColumnType(raw: string): string | null {
  const s = String(raw ?? "").trim();
  const m = /^([A-Za-z]+)\s*(\(\s*\d{1,4}\s*(,\s*\d{1,4}\s*)?\))?$/.exec(s);
  if (!m) return null;
  const base = m[1].toUpperCase();
  const ALLOWED = new Set([
    "TINYINT", "SMALLINT", "MEDIUMINT", "INT", "INTEGER", "BIGINT",
    "DECIMAL", "NUMERIC", "FLOAT", "DOUBLE", "BIT",
    "DATE", "DATETIME", "TIMESTAMP", "TIME", "YEAR",
    "CHAR", "VARCHAR", "BINARY", "VARBINARY",
    "TINYTEXT", "TEXT", "MEDIUMTEXT", "LONGTEXT",
    "TINYBLOB", "BLOB", "MEDIUMBLOB", "LONGBLOB",
    "JSON", "BOOLEAN", "BOOL",
  ]);
  if (!ALLOWED.has(base)) return null;
  const len = m[2] ? m[2].replace(/\s+/g, "") : "";
  return `${base}${len}`;
}

export function truncateTableSql(table: string): string {
  return `TRUNCATE TABLE ${quoteIdent(table)};`;
}
export function dropTableSql(table: string): string {
  return `DROP TABLE ${quoteIdent(table)};`;
}
export function renameTableSql(table: string, to: string): string {
  return `RENAME TABLE ${quoteIdent(table)} TO ${quoteIdent(to)};`;
}
/** OPTIMIZE / ANALYZE — `op` is a caller-chosen literal keyword, never user text. */
export function maintainTableSql(op: "OPTIMIZE" | "ANALYZE", table: string): string {
  const kw = op === "ANALYZE" ? "ANALYZE" : "OPTIMIZE";
  return `${kw} TABLE ${quoteIdent(table)};`;
}
/** ADD COLUMN. `typeDef` MUST already be normalizeColumnType output. */
export function addColumnSql(table: string, name: string, typeDef: string, nullable: boolean): string {
  return `ALTER TABLE ${quoteIdent(table)} ADD COLUMN ${quoteIdent(name)} ${typeDef} ${nullable ? "NULL" : "NOT NULL"};`;
}
export function dropColumnSql(table: string, name: string): string {
  return `ALTER TABLE ${quoteIdent(table)} DROP COLUMN ${quoteIdent(name)};`;
}
/** ADD [UNIQUE] INDEX over one-or-more validated columns. `indexName` is a
 *  validated simple identifier. */
export function addIndexSql(table: string, indexName: string, cols: string[], unique: boolean): string {
  const colList = cols.map(quoteIdent).join(", ");
  return `ALTER TABLE ${quoteIdent(table)} ADD ${unique ? "UNIQUE " : ""}INDEX ${quoteIdent(indexName)} (${colList});`;
}
export function dropIndexSql(table: string, indexName: string): string {
  return `ALTER TABLE ${quoteIdent(table)} DROP INDEX ${quoteIdent(indexName)};`;
}

// ---- SQL statement splitter (for Import) ------------------------------------
// Split a pasted / uploaded script into individual statements so each one can be
// run on its own through runScopedSql (multipleStatements stays OFF — we never
// ship a stacked query). Quote-, backtick- and comment-aware so a `;` inside a
// string/identifier/comment doesn't split a statement. This is a plain string
// scan; it grants no new capability — every produced statement still passes
// through the same scoped, capped transport as a hand-typed query.

/** Max statements we will run from one Import (bounds a giant paste). */
export const MAX_IMPORT_STATEMENTS = 200;

export function splitSqlStatements(script: string): string[] {
  const src = String(script ?? "");
  const out: string[] = [];
  let buf = "";
  let i = 0;
  const n = src.length;
  type Q = "'" | '"' | "`" | null;
  let quote: Q = null;
  while (i < n) {
    const ch = src[i];
    const next = src[i + 1];
    if (quote) {
      buf += ch;
      if (ch === "\\" && quote !== "`") {
        // Backslash escape inside '...'/"..." — consume the escaped char.
        if (i + 1 < n) { buf += src[i + 1]; i += 2; continue; }
      }
      if (ch === quote) {
        // A doubled quote is an escaped quote, not a close.
        if (next === quote) { buf += next; i += 2; continue; }
        quote = null;
      }
      i += 1;
      continue;
    }
    // Not in a string/identifier: handle comments.
    if ((ch === "-" && next === "-") || ch === "#") {
      // Line comment to end of line (drop it).
      while (i < n && src[i] !== "\n") i += 1;
      continue;
    }
    if (ch === "/" && next === "*") {
      i += 2;
      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) i += 1;
      i += 2;
      continue;
    }
    if (ch === "'" || ch === '"' || ch === "`") { quote = ch as Q; buf += ch; i += 1; continue; }
    if (ch === ";") { const t = buf.trim(); if (t) out.push(t); buf = ""; i += 1; continue; }
    buf += ch;
    i += 1;
  }
  const tail = buf.trim();
  if (tail) out.push(tail);
  return out;
}

