/** One per-column filter the browse grid sends: a real column name + a substring
 *  matched with LIKE. Multiple filters are ANDed. */
export type DbMgrFilter = { column: string; value: string };
export type DbMgrBrowseOpts = {
  page?: number;
  pageSize?: number;
  sortColumn?: string;
  sortDir?: "ASC" | "DESC";
  /** Per-column LIKE filters (ANDed). Unknown columns are dropped. */
  filters?: DbMgrFilter[];
  /** A quick-search term ORed (as LIKE) across the table's text columns. */
  search?: string;
};
export type DbMgrBrowseResult = {
  error?: string;
  columns?: string[];
  rows?: string[][];
  total?: number | null;
  page?: number;
  pageSize?: number;
  truncated?: boolean;
  sortColumn?: string | null;
  sortDir?: "ASC" | "DESC";
};

/** Text-ish column types the global quick-search targets. */
const TEXTY_TYPE_RE = /char|text|enum|set|json/i;

/** Browse a page of a table's rows. Validates the table by MEMBERSHIP against the
 *  db's real table list (so a user can't name a table they can't see), then runs
 *  a bounded SELECT + a COUNT. Supports per-column LIKE filters, a global quick
 *  search across text columns, sorting, and a chosen page size — all identifiers
 *  membership-validated, all values `?`-bound. Owner-or-admin + not-impersonating. */
export async function dbmgrBrowseTable(
  accountId: string,
  dbName: string,
  table: string,
  opts: DbMgrBrowseOpts = {},
): Promise<DbMgrBrowseResult> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { error: ctx.error };
  await assertNotImpersonating();
  const { user } = ctx;
  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
  if (!isPlausibleTableName(table)) return { error: "Invalid table name." };
  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
  const p = Math.max(0, Math.floor(Number(opts.page) || 0));
  const pageSize = clampPageSize(opts.pageSize ?? BROWSE_PAGE_SIZE);
  const dir: "ASC" | "DESC" = opts.sortDir === "DESC" ? "DESC" : "ASC";
  const search = String(opts.search ?? "").trim();

  if (SANDBOX) {
    const demo = sandboxResult("select");
    return { columns: demo.columns, rows: demo.rows, total: demo.rows.length, page: p, pageSize, truncated: false, sortColumn: opts.sortColumn ?? null, sortDir: dir };
  }
  const target = dbTargetFor(ctx.a);
  if (!target) return { error: "The database manager is still being prepared." };

  // Membership check: the table MUST be one the scoped user can actually see.
  const listed = await runScopedSql(target, dbName, showTablesSql());
  if (listed.error) return { error: listed.error };
  const tables = listed.rows.map((r) => r[0]);
  if (!tables.includes(table)) return { error: "Unknown table." };

  // Load the real columns (name + type) once — the sole source for validating
  // every identifier we embed (sort col, filter cols, search cols).
  const colsRes = await runScopedSql(target, dbName, showFullColumnsSql(table));
  if (colsRes.error) return { error: colsRes.error };
  const realCols = colsRes.rows.map((r) => r[0]);
  const realSet = new Set(realCols);
  const textCols = colsRes.rows.filter((r) => TEXTY_TYPE_RE.test(r[1] ?? "")).map((r) => r[0]);

  // Sort column validated by MEMBERSHIP before it can be backtick-quoted.
  let order: { col: string; dir: "ASC" | "DESC" } | undefined;
  if (opts.sortColumn && realSet.has(opts.sortColumn)) order = { col: opts.sortColumn, dir };

  // Per-column filters: keep only real columns; bind each value as `%v%`.
  const filterCols: string[] = [];
  const filterValues: string[] = [];
  for (const f of opts.filters ?? []) {
    if (f && realSet.has(f.column) && String(f.value ?? "") !== "") {
      filterCols.push(f.column);
      filterValues.push(`%${likeEscape(String(f.value))}%`);
    }
  }
  // Global search: OR LIKE across text columns (all columns if none are texty),
  // one bound `%term%` per column.
  const searchCols = search ? (textCols.length ? textCols : realCols) : [];
  const searchValues = searchCols.map(() => `%${likeEscape(search)}%`);

  const hasFilter = filterCols.length > 0 || searchCols.length > 0;
  const sql = hasFilter
    ? filteredBrowseSql(table, filterCols, searchCols, pageSize, p * pageSize, order)
    : browseTableSql(table, pageSize, p * pageSize, order);
  const params = [...filterValues, ...searchValues];
  const res = await runScopedSql(target, dbName, sql, hasFilter ? params : undefined);
  if (res.error) return { error: res.error };

  const countSql = hasFilter ? countFilteredSql(table, filterCols, searchCols) : countTableSql(table);
  const countRes = await runScopedSql(target, dbName, countSql, hasFilter ? params : undefined);
  const total = countRes.error ? null : Number(countRes.rows[0]?.[0] ?? "0");
  return { columns: res.columns, rows: res.rows, total: Number.isFinite(total as number) ? (total as number) : null, page: p, pageSize, truncated: res.truncated, sortColumn: order?.col ?? null, sortDir: dir };
}

/** Escape the LIKE metacharacters `%` and `_` (and the escape char) in a
 *  user search term so they match literally inside our `%…%` wrapper. The value
 *  is still bound as a `?` param — this only stops a user `%` widening the match. */
function likeEscape(s: string): string {
  return s.replace(/[\\%_]/g, (c) => `\\${c}`);
}

