/* ───────────────────────────── Database overview ─────────────────────────── */

export type DbMgrOverviewTable = {
  name: string;
  rows: number | null;
  dataBytes: number | null;
  indexBytes: number | null;
  engine: string | null;
  collation: string | null;
};

/** Every base table in the database with approximate row count, data/index size,
 *  engine and collation (information_schema, schema bound as `?`). Powers the
 *  "no table selected" overview. Owner-or-admin + not-impersonating. */
export async function dbmgrDatabaseOverview(accountId: string, dbName: string): Promise<{ error?: string; tables?: DbMgrOverviewTable[] }> {
  const lt = await liveTarget(accountId, dbName);
  if ("error" in lt) return { error: lt.error };
  if (lt.mode === "sandbox") {
    return {
      tables: [
        { name: "customers", rows: 42, dataBytes: 16384, indexBytes: 16384, engine: "InnoDB", collation: "utf8mb4_general_ci" },
        { name: "orders", rows: 17, dataBytes: 32768, indexBytes: 16384, engine: "InnoDB", collation: "utf8mb4_general_ci" },
        { name: "products", rows: 88, dataBytes: 49152, indexBytes: 16384, engine: "InnoDB", collation: "utf8mb4_general_ci" },
      ],
    };
  }
  const res = await runScopedSql(lt.target, dbName, overviewSql(), [dbName]);
  if (res.error) return { error: res.error };
  const num = (v: string) => (v === NULL_SENTINEL ? null : (Number(v) || 0));
  const str = (v: string) => (v === NULL_SENTINEL ? null : v || null);
  return {
    tables: res.rows.map((r) => ({
      name: r[0],
      rows: num(r[1]),
      dataBytes: num(r[2]),
      indexBytes: num(r[3]),
      engine: str(r[4]),
      collation: str(r[5]),
    })),
  };
}

/* ─────────────────────────── Table operations (DDL) ──────────────────────────
 * truncate / drop / rename / optimize / analyze / add-column / drop-column /
 * add-index / drop-index. Every one: owner-or-admin, not-impersonating, owned-db,
 * rate-limited, TABLE validated by membership. New object names go through
 * isSimpleIdent; a new column's type through normalizeColumnType; existing
 * columns/indexes through membership against the live structure. No user VALUES
 * are ever embedded (there are none in this DDL), and everything runs through the
 * scoped `runScopedSql` transport — the MySQL grant remains the hard boundary. */

async function ddlPreamble(accountId: string, dbName: string, table: string) {
  const lt = await liveTarget(accountId, dbName);
  if ("error" in lt) return { error: lt.error } as const;
  if (lt.mode === "sandbox") return { mode: "sandbox" } as const;
  const vis = await tableIsVisible(lt.target, dbName, table);
  if ("error" in vis) return { error: vis.error } as const;
  return { mode: "live", target: lt.target } as const;
}

const okResult: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0, ok: true };

export async function dbmgrTruncateTable(accountId: string, dbName: string, table: string): Promise<DbMgrResult> {
  const pre = await ddlPreamble(accountId, dbName, table);
  if ("error" in pre) return { ...okResult, ok: false, error: pre.error };
  if (pre.mode === "sandbox") return okResult;
  const res = await runScopedSql(pre.target, dbName, truncateTableSql(table));
  return res.error ? { ...res, ok: false } : { ...res, ok: true };
}

export async function dbmgrDropTable(accountId: string, dbName: string, table: string): Promise<DbMgrResult> {
  const pre = await ddlPreamble(accountId, dbName, table);
  if ("error" in pre) return { ...okResult, ok: false, error: pre.error };
  if (pre.mode === "sandbox") return okResult;
  const res = await runScopedSql(pre.target, dbName, dropTableSql(table));
  return res.error ? { ...res, ok: false } : { ...res, ok: true };
}

export async function dbmgrRenameTable(accountId: string, dbName: string, table: string, to: string): Promise<DbMgrResult> {
  if (!isSimpleIdent(to)) return { ...okResult, ok: false, error: "New name must be letters, digits or underscores (max 64)." };
  const pre = await ddlPreamble(accountId, dbName, table);
  if ("error" in pre) return { ...okResult, ok: false, error: pre.error };
  if (pre.mode === "sandbox") return okResult;
  const res = await runScopedSql(pre.target, dbName, renameTableSql(table, to));
  return res.error ? { ...res, ok: false } : { ...res, ok: true };
}

export async function dbmgrMaintainTable(accountId: string, dbName: string, table: string, op: "OPTIMIZE" | "ANALYZE"): Promise<DbMgrResult> {
  const kw = op === "ANALYZE" ? "ANALYZE" : "OPTIMIZE";
  const pre = await ddlPreamble(accountId, dbName, table);
  if ("error" in pre) return { ...okResult, ok: false, error: pre.error };
  if (pre.mode === "sandbox") return { ...okResult, columns: ["Table", "Op", "Msg_type", "Msg_text"], rows: [[table, kw.toLowerCase(), "status", "OK"]] };
  const res = await runScopedSql(pre.target, dbName, maintainTableSql(kw, table));
  // OPTIMIZE/ANALYZE return a status result set — surface it.
  return res.error ? { ...res, ok: false } : { ...res, ok: true };
}

export async function dbmgrAddColumn(accountId: string, dbName: string, table: string, name: string, type: string, nullable: boolean): Promise<DbMgrResult> {
  if (!isSimpleIdent(name)) return { ...okResult, ok: false, error: "Column name must be letters, digits or underscores (max 64)." };
  const typeDef = normalizeColumnType(type);
  if (!typeDef) return { ...okResult, ok: false, error: "Unsupported column type. Use e.g. VARCHAR(255), INT, DATETIME, TEXT." };
  const pre = await ddlPreamble(accountId, dbName, table);
  if ("error" in pre) return { ...okResult, ok: false, error: pre.error };
  if (pre.mode === "sandbox") return okResult;
  const res = await runScopedSql(pre.target, dbName, addColumnSql(table, name, typeDef, nullable));
  return res.error ? { ...res, ok: false } : { ...res, ok: true };
}

export async function dbmgrDropColumn(accountId: string, dbName: string, table: string, column: string): Promise<DbMgrResult> {
  const pre = await ddlPreamble(accountId, dbName, table);
  if ("error" in pre) return { ...okResult, ok: false, error: pre.error };
  if (pre.mode === "sandbox") return okResult;
  // Membership: `column` must be a real column of this table.
  const s = await fetchStructure(pre.target, dbName, table);
  if ("error" in s) return { ...okResult, ok: false, error: s.error };
  if (!s.structure.columns.some((c) => c.name === column)) return { ...okResult, ok: false, error: "Unknown column." };
  const res = await runScopedSql(pre.target, dbName, dropColumnSql(table, column));
  return res.error ? { ...res, ok: false } : { ...res, ok: true };
}

export async function dbmgrAddIndex(accountId: string, dbName: string, table: string, indexName: string, columns: string[], unique: boolean): Promise<DbMgrResult> {
  if (!isSimpleIdent(indexName)) return { ...okResult, ok: false, error: "Index name must be letters, digits or underscores (max 64)." };
  const pre = await ddlPreamble(accountId, dbName, table);
  if ("error" in pre) return { ...okResult, ok: false, error: pre.error };
  if (pre.mode === "sandbox") return okResult;
  const s = await fetchStructure(pre.target, dbName, table);
  if ("error" in s) return { ...okResult, ok: false, error: s.error };
  const real = new Set(s.structure.columns.map((c) => c.name));
  const cols = (columns ?? []).filter((c) => real.has(c));
  if (cols.length === 0) return { ...okResult, ok: false, error: "Pick at least one column to index." };
  const res = await runScopedSql(pre.target, dbName, addIndexSql(table, indexName, cols, unique));
  return res.error ? { ...res, ok: false } : { ...res, ok: true };
}

export async function dbmgrDropIndex(accountId: string, dbName: string, table: string, indexName: string): Promise<DbMgrResult> {
  const pre = await ddlPreamble(accountId, dbName, table);
  if ("error" in pre) return { ...okResult, ok: false, error: pre.error };
  if (pre.mode === "sandbox") return okResult;
  const s = await fetchStructure(pre.target, dbName, table);
  if ("error" in s) return { ...okResult, ok: false, error: s.error };
  if (!s.structure.indexes.some((i) => i.name === indexName)) return { ...okResult, ok: false, error: "Unknown index." };
  const res = await runScopedSql(pre.target, dbName, dropIndexSql(table, indexName));
  return res.error ? { ...res, ok: false } : { ...res, ok: true };
}

/* ───────────────────────────────── Import ────────────────────────────────── */

export type DbMgrImportStatement = { sql: string; ok: boolean; error: string | null; rows: number; elapsedMs: number };
export type DbMgrImportResult = { error?: string; results?: DbMgrImportStatement[]; ranAll?: boolean };

/** Run a pasted / uploaded SQL script statement-by-statement. The script is split
 *  locally (quote/comment-aware) and each statement is shipped on its own through
 *  the scoped, capped `runScopedSql` transport (multipleStatements stays OFF — we
 *  never send a stacked query). Stops at the first error and reports per-statement
 *  results. Owner-or-admin + not-impersonating + rate-limited. */
export async function dbmgrImportSql(accountId: string, dbName: string, script: string): Promise<DbMgrImportResult> {
  const lt = await liveTarget(accountId, dbName);
  if ("error" in lt) return { error: lt.error };
  const text = String(script ?? "");
  if (!text.trim()) return { error: "Paste or upload a SQL script to import." };
  if (Buffer.byteLength(text, "utf8") > MAX_SQL_BYTES * 8) return { error: "That script is too large to import here — split it into smaller files." };
  const statements = splitSqlStatements(text);
  if (statements.length === 0) return { error: "No runnable statements found." };
  if (statements.length > MAX_IMPORT_STATEMENTS) return { error: `Too many statements (${statements.length}); the import cap is ${MAX_IMPORT_STATEMENTS}. Split the file.` };

  if (lt.mode === "sandbox") {
    return { results: statements.map((s) => ({ sql: s, ok: true, error: null, rows: 0, elapsedMs: 1 })), ranAll: true };
  }

  const results: DbMgrImportStatement[] = [];
  for (const stmt of statements) {
    const res = await runScopedSql(lt.target, dbName, stmt);
    results.push({ sql: stmt, ok: !res.error, error: res.error, rows: res.rows.length, elapsedMs: res.elapsedMs });
    if (res.error) return { results, ranAll: false }; // stop at the first failure
  }
  return { results, ranAll: true };
}

