"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Badge } from "@/components/ui/primitives";
import {
  ensureDbManager,
  dbmgrStatus,
  dbmgrListDatabases,
  dbmgrTableCounts,
  dbmgrDatabaseOverview,
  dbmgrBrowseTable,
  dbmgrRunSql,
  dbmgrTableStructure,
  dbmgrInsertRow,
  dbmgrUpdateRow,
  dbmgrDeleteRow,
  dbmgrExportTable,
  dbmgrImportSql,
  dbmgrTruncateTable,
  dbmgrDropTable,
  dbmgrRenameTable,
  dbmgrMaintainTable,
  dbmgrAddColumn,
  dbmgrDropColumn,
  dbmgrAddIndex,
  dbmgrDropIndex,
  type DbMgrDatabase,
  type DbMgrTableInfo,
  type DbMgrOverviewTable,
  type DbMgrStructure,
  type DbMgrColumn,
  type DbMgrFilter,
  type DbCellValue,
} from "@/lib/actions-hosting-db";

/**
 * Nxeon DB Studio — the PROPRIETARY, in-portal database manager (a phpMyAdmin-class
 * experience with the Nxeon design system). Every action runs SERVER-SIDE as the
 * account's scoped `<username>_mgr` MySQL user over an SSH-tunnelled mysql2 session
 * (see lib/hosting-db.ts): the browser never holds a DB credential and the grant is
 * the isolation boundary, so it can only ever touch this account's own databases.
 */
export function DbManager({ accountId }: { accountId: string }) {
  const [status, setStatus] = useState<"loading" | "provisioning" | "ready" | "error">("loading");
  const [statusMsg, setStatusMsg] = useState("");
  const [databases, setDatabases] = useState<DbMgrDatabase[]>([]);
  const [activeDb, setActiveDb] = useState<string>("");
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const [ens, list] = await Promise.all([ensureDbManager(accountId), dbmgrListDatabases(accountId)]);
      if (cancelled) return;
      if (list.databases) {
        setDatabases(list.databases);
        const firstActive = list.databases.find((d) => d.status === "ACTIVE") ?? list.databases[0];
        if (firstActive) setActiveDb(firstActive.name);
      }
      if (ens.error) { setStatus("error"); setStatusMsg(ens.error); return; }
      if (ens.ready) { setStatus("ready"); return; }
      setStatus("provisioning");
    })();
    return () => { cancelled = true; };
  }, [accountId]);

  useEffect(() => {
    if (status !== "provisioning") return;
    let tries = 0;
    pollRef.current = setInterval(async () => {
      tries++;
      const s = await dbmgrStatus(accountId);
      if (s.ready) { setStatus("ready"); if (pollRef.current) clearInterval(pollRef.current); return; }
      if (tries >= 20) { setStatus("error"); setStatusMsg("The database manager is taking longer than expected to set up. Try again shortly."); if (pollRef.current) clearInterval(pollRef.current); }
    }, 3000);
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, [status, accountId]);

  const activeDbs = databases.filter((d) => d.status === "ACTIVE");

  return (
    <div className="overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/60 backdrop-blur-md">
      {/* Studio header */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/[0.06] bg-gradient-to-r from-accent-blue/[0.08] to-brand-500/[0.06] px-4 py-3">
        <div className="flex items-center gap-2.5">
          <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-accent-blue to-brand-500 text-[13px] font-bold text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]">N</span>
          <div>
            <h3 className="text-sm font-semibold text-slate-100">Nxeon DB Studio</h3>
            <p className="text-[11px] text-slate-500">Browse, query &amp; edit your databases</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {status === "ready" && <Badge tone="green">connected</Badge>}
          {status === "provisioning" && <Badge tone="amber">preparing</Badge>}
          {status === "error" && <Badge tone="red">unavailable</Badge>}
        </div>
      </div>

      <div className="p-4">
        {status === "loading" && <SkeletonStudio />}
        {status === "provisioning" && (
          <div className="flex items-center gap-3 rounded-xl border border-amber-500/20 bg-amber-500/[0.06] px-4 py-3">
            <Spinner />
            <p className="text-xs text-amber-200">Preparing your secure database connection… this only happens once.</p>
          </div>
        )}
        {status === "error" && (
          <div className="rounded-xl border border-red-500/20 bg-red-500/[0.06] px-4 py-3 text-xs text-red-200">{statusMsg || "The database manager is unavailable right now."}</div>
        )}

        {status === "ready" && databases.length === 0 && (
          <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-10 text-center">
            <DatabaseIcon className="mx-auto mb-3 h-8 w-8 text-brand-300/70" />
            <p className="text-sm font-medium text-slate-200">No databases yet</p>
            <p className="mx-auto mt-1 max-w-sm text-xs text-slate-500">Create your first database below, then come back to browse tables, run queries and edit rows here.</p>
          </div>
        )}

        {status === "ready" && databases.length > 0 && (
          <Studio
            key={activeDb}
            accountId={accountId}
            databases={databases}
            activeDbs={activeDbs}
            activeDb={activeDb}
            onPickDb={setActiveDb}
          />
        )}
      </div>
    </div>
  );
}

/* ================================================================= Studio === */

type MainTab = "overview" | "browse" | "structure" | "sql" | "import";

function Studio({
  accountId,
  databases,
  activeDbs,
  activeDb,
  onPickDb,
}: {
  accountId: string;
  databases: DbMgrDatabase[];
  activeDbs: DbMgrDatabase[];
  activeDb: string;
  onPickDb: (db: string) => void;
}) {
  const [tables, setTables] = useState<DbMgrTableInfo[]>([]);
  const [tablesErr, setTablesErr] = useState("");
  const [tablesBusy, setTablesBusy] = useState(true);
  const [filter, setFilter] = useState("");
  const [activeTable, setActiveTable] = useState<string>("");
  const [tab, setTab] = useState<MainTab>("overview");

  const loadTables = useCallback(async () => {
    setTablesBusy(true); setTablesErr("");
    const res = await dbmgrTableCounts(accountId, activeDb);
    setTablesBusy(false);
    if (res.error) { setTablesErr(res.error); setTables([]); return; }
    setTables(res.tables ?? []);
  }, [accountId, activeDb]);

  useEffect(() => { loadTables(); }, [loadTables]);

  const filtered = useMemo(() => {
    const q = filter.trim().toLowerCase();
    return q ? tables.filter((t) => t.name.toLowerCase().includes(q)) : tables;
  }, [tables, filter]);

  function openTable(name: string) {
    setActiveTable(name);
    setTab((t) => (t === "sql" || t === "import" || t === "overview" ? "browse" : t));
  }

  // A table was renamed/dropped elsewhere — refresh the tree + reconcile selection.
  const onTablesChanged = useCallback((opts?: { removed?: string; renamedTo?: string }) => {
    if (opts?.removed && opts.removed === activeTable) { setActiveTable(""); setTab("overview"); }
    if (opts?.renamedTo) setActiveTable(opts.renamedTo);
    loadTables();
  }, [activeTable, loadTables]);

  return (
    <div className="grid gap-4 lg:grid-cols-[15rem_minmax(0,1fr)]">
      {/* Sidebar */}
      <aside className="flex flex-col gap-3">
        {/* Database picker */}
        <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
          <p className="section-label mb-2 flex items-center gap-1.5"><DatabaseIcon className="h-3.5 w-3.5" /> Database</p>
          {activeDbs.length > 1 ? (
            <select className="input py-2 text-xs" value={activeDb} onChange={(e) => onPickDb(e.target.value)}>
              {databases.map((d) => (
                <option key={d.name} value={d.name} disabled={d.status !== "ACTIVE"}>
                  {d.name}{d.status !== "ACTIVE" ? ` (${d.status.toLowerCase()})` : ""}
                </option>
              ))}
            </select>
          ) : (
            <button
              type="button"
              onClick={() => { setActiveTable(""); setTab("overview"); }}
              className="w-full truncate rounded-lg border border-white/[0.06] bg-navy-900/60 px-2.5 py-2 text-left font-mono text-xs text-slate-200 hover:border-brand-500/30"
              title={`${activeDb} — database overview`}
            >
              {activeDb}
            </button>
          )}
        </div>

        {/* Tables tree */}
        <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
          <div className="mb-2 flex items-center justify-between">
            <p className="section-label flex items-center gap-1.5"><TableIcon className="h-3.5 w-3.5" /> Tables {tables.length > 0 && <span className="text-slate-600">({tables.length})</span>}</p>
            <button type="button" className="btn-ghost rounded-md px-1.5 py-1 text-[11px]" onClick={loadTables} title="Refresh tables"><RefreshIcon className="h-3.5 w-3.5" /></button>
          </div>
          <div className="relative mb-2">
            <SearchIcon className="pointer-events-none absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-500" />
            <input className="input py-1.5 pl-8 text-xs" placeholder="Filter tables…" value={filter} onChange={(e) => setFilter(e.target.value)} />
          </div>
          {tablesBusy && <div className="space-y-1.5 py-1">{[0, 1, 2, 3].map((i) => <div key={i} className="skeleton h-6" />)}</div>}
          {tablesErr && <p className="rounded-lg border border-red-500/20 bg-red-500/[0.06] px-2 py-1.5 text-[11px] text-red-200">{tablesErr}</p>}
          {!tablesBusy && !tablesErr && tables.length === 0 && <p className="px-1 py-2 text-[11px] text-slate-500">This database has no tables yet. Create one from the SQL or Import tab.</p>}
          {!tablesBusy && !tablesErr && tables.length > 0 && filtered.length === 0 && <p className="px-1 py-2 text-[11px] text-slate-500">No tables match “{filter}”.</p>}
          <ul className="max-h-[20rem] space-y-0.5 overflow-y-auto">
            {filtered.map((t) => {
              const active = activeTable === t.name && tab !== "sql" && tab !== "import" && tab !== "overview";
              return (
                <li key={t.name}>
                  <button
                    type="button"
                    onClick={() => openTable(t.name)}
                    className={`group flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left transition-colors ${active ? "bg-gradient-to-r from-accent-blue/20 to-brand-500/20 text-brand-100" : "text-slate-300 hover:bg-white/[0.04]"}`}
                    title={t.name}
                  >
                    <TableIcon className={`h-3.5 w-3.5 shrink-0 ${active ? "text-brand-200" : "text-slate-500 group-hover:text-slate-400"}`} />
                    <span className="min-w-0 flex-1 truncate font-mono text-xs">{t.name}</span>
                    {t.rows != null && <span className="shrink-0 rounded-full bg-white/[0.06] px-1.5 py-0.5 text-[10px] tabular-nums text-slate-400">{fmtCount(t.rows)}</span>}
                  </button>
                </li>
              );
            })}
          </ul>
        </div>

        <div className="grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={() => setTab("sql")}
            className={`flex items-center justify-center gap-1.5 rounded-xl border px-2 py-2.5 text-xs font-semibold transition-colors ${tab === "sql" ? "border-brand-500/40 bg-brand-500/15 text-brand-100" : "border-white/[0.06] bg-white/[0.02] text-slate-300 hover:bg-white/[0.05]"}`}
          >
            <SqlIcon className="h-4 w-4" /> SQL
          </button>
          <button
            type="button"
            onClick={() => setTab("import")}
            className={`flex items-center justify-center gap-1.5 rounded-xl border px-2 py-2.5 text-xs font-semibold transition-colors ${tab === "import" ? "border-brand-500/40 bg-brand-500/15 text-brand-100" : "border-white/[0.06] bg-white/[0.02] text-slate-300 hover:bg-white/[0.05]"}`}
          >
            <UploadIcon className="h-4 w-4" /> Import
          </button>
        </div>
      </aside>

      {/* Main pane */}
      <section className="min-w-0">
        <div className="mb-3 flex flex-wrap items-center gap-1 border-b border-white/[0.06] pb-2">
          <TabButton active={tab === "overview"} onClick={() => { setActiveTable(""); setTab("overview"); }} icon={<DatabaseIcon className="h-3.5 w-3.5" />}>Overview</TabButton>
          <TabButton active={tab === "browse"} disabled={!activeTable} onClick={() => setTab("browse")} icon={<GridIcon className="h-3.5 w-3.5" />}>Browse</TabButton>
          <TabButton active={tab === "structure"} disabled={!activeTable} onClick={() => setTab("structure")} icon={<ColumnsIcon className="h-3.5 w-3.5" />}>Structure</TabButton>
          <TabButton active={tab === "sql"} onClick={() => setTab("sql")} icon={<SqlIcon className="h-3.5 w-3.5" />}>SQL</TabButton>
          <TabButton active={tab === "import"} onClick={() => setTab("import")} icon={<UploadIcon className="h-3.5 w-3.5" />}>Import</TabButton>
          {activeTable && (tab === "browse" || tab === "structure") && (
            <span className="ml-auto flex items-center gap-1.5 font-mono text-xs text-slate-400"><TableIcon className="h-3.5 w-3.5 text-brand-300" />{activeTable}</span>
          )}
        </div>

        {tab === "overview" && <OverviewPanel accountId={accountId} dbName={activeDb} onOpenTable={openTable} />}
        {tab === "sql" && <SqlEditor accountId={accountId} dbName={activeDb} onChanged={loadTables} />}
        {tab === "import" && <ImportPanel accountId={accountId} dbName={activeDb} onChanged={loadTables} />}
        {(tab === "browse" || tab === "structure") && !activeTable && (
          <div className="rounded-xl border border-dashed border-white/[0.08] bg-white/[0.01] px-4 py-12 text-center">
            <TableIcon className="mx-auto mb-3 h-7 w-7 text-slate-600" />
            <p className="text-sm text-slate-300">Pick a table to get started</p>
            <p className="mx-auto mt-1 max-w-xs text-xs text-slate-500">Choose a table from the sidebar to browse its rows and edit its structure, or open the SQL editor.</p>
          </div>
        )}
        {tab === "browse" && activeTable && (
          <TableBrowser key={`${activeDb}/${activeTable}`} accountId={accountId} dbName={activeDb} table={activeTable} onDataChanged={loadTables} />
        )}
        {tab === "structure" && activeTable && (
          <StructureView key={`${activeDb}/${activeTable}/s`} accountId={accountId} dbName={activeDb} table={activeTable} onChanged={onTablesChanged} onEditData={() => setTab("browse")} />
        )}
      </section>
    </div>
  );
}

/* ============================================================= OverviewPanel === */

function OverviewPanel({ accountId, dbName, onOpenTable }: { accountId: string; dbName: string; onOpenTable: (t: string) => void }) {
  const [tables, setTables] = useState<DbMgrOverviewTable[] | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(true);

  const load = useCallback(async () => {
    setBusy(true); setErr("");
    const res = await dbmgrDatabaseOverview(accountId, dbName);
    setBusy(false);
    if (res.error) { setErr(res.error); setTables(null); return; }
    setTables(res.tables ?? []);
  }, [accountId, dbName]);
  useEffect(() => { load(); }, [load]);

  const totals = useMemo(() => {
    const t = tables ?? [];
    return {
      tables: t.length,
      rows: t.reduce((a, x) => a + (x.rows ?? 0), 0),
      data: t.reduce((a, x) => a + (x.dataBytes ?? 0), 0),
      index: t.reduce((a, x) => a + (x.indexBytes ?? 0), 0),
    };
  }, [tables]);

  return (
    <div>
      <div className="mb-3 flex items-center justify-between">
        <div>
          <h4 className="flex items-center gap-2 text-sm font-semibold text-slate-100"><DatabaseIcon className="h-4 w-4 text-brand-300" /> <span className="font-mono">{dbName}</span></h4>
          <p className="mt-0.5 text-[11px] text-slate-500">Database overview — every table with approximate rows, size, engine and collation.</p>
        </div>
        <button className="btn-ghost rounded-lg px-2 py-1.5 text-xs" onClick={load} title="Refresh"><RefreshIcon className="h-3.5 w-3.5" /></button>
      </div>

      {!busy && !err && tables && tables.length > 0 && (
        <div className="mb-3 grid grid-cols-2 gap-2 sm:grid-cols-4">
          <OverviewStat label="Tables" value={totals.tables.toLocaleString()} />
          <OverviewStat label="Rows (approx)" value={totals.rows.toLocaleString()} />
          <OverviewStat label="Data" value={fmtBytes(totals.data)} />
          <OverviewStat label="Indexes" value={fmtBytes(totals.index)} />
        </div>
      )}

      {err && <ErrorBanner msg={err} onClose={() => setErr("")} />}
      {busy ? (
        <GridSkeleton />
      ) : tables && tables.length === 0 ? (
        <div className="rounded-xl border border-dashed border-white/[0.08] bg-white/[0.01] px-4 py-10 text-center">
          <TableIcon className="mx-auto mb-2 h-6 w-6 text-slate-600" />
          <p className="text-sm text-slate-300">No tables in this database yet</p>
          <p className="mx-auto mt-1 max-w-xs text-xs text-slate-500">Create one from the SQL editor or the Import tab.</p>
        </div>
      ) : tables ? (
        <div className="overflow-x-auto rounded-xl border border-white/[0.06]">
          <table className="min-w-full text-left text-xs">
            <thead className="bg-white/[0.03]">
              <tr>
                {["Table", "Rows", "Data", "Index", "Engine", "Collation"].map((h, i) => (
                  <th key={h} className={`whitespace-nowrap border-b border-white/[0.06] px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500 ${i > 0 && i < 4 ? "text-right" : ""}`}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {tables.map((t) => (
                <tr key={t.name} className="border-t border-white/[0.04] transition-colors odd:bg-white/[0.01] hover:bg-white/[0.03]">
                  <td className="whitespace-nowrap px-3 py-1.5">
                    <button type="button" onClick={() => onOpenTable(t.name)} className="inline-flex items-center gap-1.5 font-mono font-medium text-brand-200 hover:text-brand-100 hover:underline">
                      <TableIcon className="h-3.5 w-3.5 text-slate-500" />{t.name}
                    </button>
                  </td>
                  <td className="px-3 py-1.5 text-right tabular-nums text-slate-300">{t.rows == null ? "·" : t.rows.toLocaleString()}</td>
                  <td className="px-3 py-1.5 text-right tabular-nums text-slate-400">{t.dataBytes == null ? "·" : fmtBytes(t.dataBytes)}</td>
                  <td className="px-3 py-1.5 text-right tabular-nums text-slate-400">{t.indexBytes == null ? "·" : fmtBytes(t.indexBytes)}</td>
                  <td className="px-3 py-1.5 text-slate-400">{t.engine ?? "·"}</td>
                  <td className="whitespace-nowrap px-3 py-1.5 font-mono text-[11px] text-slate-500">{t.collation ?? "·"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : null}
    </div>
  );
}

function OverviewStat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2">
      <p className="text-[10px] uppercase tracking-wider text-slate-500">{label}</p>
      <p className="mt-0.5 text-sm font-semibold tabular-nums text-slate-100">{value}</p>
    </div>
  );
}

/* ============================================================ TableBrowser === */

type Sort = { col: string; dir: "ASC" | "DESC" } | null;

function TableBrowser({ accountId, dbName, table, onDataChanged }: { accountId: string; dbName: string; table: string; onDataChanged: () => void }) {
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(50);
  const [sort, setSort] = useState<Sort>(null);
  const [reload, setReload] = useState(0);
  const [data, setData] = useState<{ columns: string[]; rows: string[][]; total: number | null; pageSize: number; truncated: boolean } | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  // Filtering: a global quick-search + per-column filters (applied on submit).
  const [search, setSearch] = useState("");
  const [appliedSearch, setAppliedSearch] = useState("");
  const [showFilters, setShowFilters] = useState(false);
  const [colFilters, setColFilters] = useState<Record<string, string>>({});
  const [appliedFilters, setAppliedFilters] = useState<DbMgrFilter[]>([]);

  // Structure powers the row editor + type-aware rendering. Loaded once per table.
  const [structure, setStructure] = useState<DbMgrStructure | null>(null);
  useEffect(() => {
    let cancelled = false;
    dbmgrTableStructure(accountId, dbName, table).then((r) => { if (!cancelled && r.structure) setStructure(r.structure); });
    return () => { cancelled = true; };
  }, [accountId, dbName, table]);

  const numericCols = useMemo(() => {
    const s = new Set<string>();
    for (const c of structure?.columns ?? []) if (isNumericType(c.type)) s.add(c.name);
    return s;
  }, [structure]);

  // Row-editor + selection state.
  const [editor, setEditor] = useState<{ mode: "insert" | "edit" | "clone"; original: Record<string, DbCellValue> | null } | null>(null);
  const [confirmDel, setConfirmDel] = useState<{ row: Record<string, DbCellValue>; label: string } | null>(null);
  const [confirmBulk, setConfirmBulk] = useState(false);
  const [selected, setSelected] = useState<Set<number>>(new Set());
  const [busyMsg, setBusyMsg] = useState("");

  useEffect(() => {
    let cancelled = false;
    setBusy(true); setErr("");
    setSelected(new Set());
    dbmgrBrowseTable(accountId, dbName, table, {
      page, pageSize, sortColumn: sort?.col, sortDir: sort?.dir,
      search: appliedSearch, filters: appliedFilters,
    }).then((res) => {
      if (cancelled) return;
      setBusy(false);
      if (res.error) { setErr(res.error); setData(null); return; }
      setData({ columns: res.columns ?? [], rows: res.rows ?? [], total: res.total ?? null, pageSize: res.pageSize ?? pageSize, truncated: !!res.truncated });
    });
    return () => { cancelled = true; };
  }, [accountId, dbName, table, page, pageSize, sort, reload, appliedSearch, appliedFilters]);

  const total = data?.total ?? null;
  const effPageSize = data?.pageSize ?? pageSize;
  const maxPage = total != null ? Math.max(0, Math.ceil(total / effPageSize) - 1) : (data && data.rows.length === effPageSize ? page + 1 : page);
  const from = data && data.rows.length ? page * effPageSize + 1 : 0;
  const to = data ? page * effPageSize + data.rows.length : 0;

  const hasActiveFilter = appliedSearch !== "" || appliedFilters.length > 0;

  function toggleSort(col: string) {
    setPage(0);
    setSort((s) => (!s || s.col !== col ? { col, dir: "ASC" } : s.dir === "ASC" ? { col, dir: "DESC" } : null));
  }

  function applyFilters() {
    setPage(0);
    setAppliedSearch(search.trim());
    setAppliedFilters(Object.entries(colFilters).filter(([, v]) => v.trim() !== "").map(([column, value]) => ({ column, value: value.trim() })));
  }
  function clearFilters() {
    setSearch(""); setColFilters({}); setPage(0);
    setAppliedSearch(""); setAppliedFilters([]);
  }

  function rowRecord(r: string[]): Record<string, DbCellValue> {
    const cols = data?.columns ?? [];
    const rec: Record<string, DbCellValue> = {};
    cols.forEach((c, i) => { rec[c] = r[i] === NULL_CELL ? null : (r[i] ?? ""); });
    return rec;
  }
  function cloneRecord(r: string[]): Record<string, DbCellValue> {
    // Pre-fill a clone but drop auto-increment / PK columns so the DB assigns fresh keys.
    const rec = rowRecord(r);
    for (const c of structure?.columns ?? []) {
      if (/auto_increment/i.test(c.extra) || c.key === "PRI") delete rec[c.name];
    }
    return rec;
  }

  async function doDelete() {
    if (!confirmDel) return;
    setBusyMsg("Deleting row…");
    const res = await dbmgrDeleteRow(accountId, dbName, table, confirmDel.row);
    setBusyMsg("");
    setConfirmDel(null);
    if (res.error) { setErr(res.error); return; }
    setReload((n) => n + 1);
    onDataChanged();
  }

  async function doBulkDelete() {
    if (!data) return;
    const rows = [...selected].sort((a, b) => a - b).map((i) => data.rows[i]).filter(Boolean);
    setConfirmBulk(false);
    let done = 0; let failed = 0; let firstErr = "";
    for (const r of rows) {
      setBusyMsg(`Deleting ${done + 1} of ${rows.length}…`);
      const res = await dbmgrDeleteRow(accountId, dbName, table, rowRecord(r));
      if (res.error) { failed++; if (!firstErr) firstErr = res.error; } else done++;
    }
    setBusyMsg("");
    setSelected(new Set());
    if (failed) setErr(`Deleted ${done} row${done === 1 ? "" : "s"}; ${failed} failed. ${firstErr}`);
    setReload((n) => n + 1);
    onDataChanged();
  }

  async function inlineSave(row: string[], col: string, value: DbCellValue): Promise<string | null> {
    const where = rowRecord(row);
    const res = await dbmgrUpdateRow(accountId, dbName, table, where, { [col]: value });
    if (res.error) return res.error;
    setReload((n) => n + 1);
    onDataChanged();
    return null;
  }

  async function exportAs(format: "sql" | "csv") {
    setBusyMsg(format === "csv" ? "Building CSV…" : "Building SQL dump…");
    const res = await dbmgrExportTable(accountId, dbName, table, format);
    setBusyMsg("");
    if (res.error) { setErr(res.error); return; }
    downloadText(res.filename ?? `${table}.${format}`, res.content ?? "", res.mime ?? "text/plain");
  }

  return (
    <div>
      {/* Toolbar */}
      <div className="mb-2 flex flex-wrap items-center gap-2">
        <button className="btn-primary px-3 py-1.5 text-xs" disabled={!structure} onClick={() => setEditor({ mode: "insert", original: null })}><PlusIcon className="h-3.5 w-3.5" /> Insert row</button>
        <ExportMenu onExport={exportAs} />
        <button
          className={`btn-secondary px-2.5 py-1.5 text-xs ${showFilters || hasActiveFilter ? "border-brand-500/40 text-brand-100" : ""}`}
          onClick={() => setShowFilters((v) => !v)}
          title="Column filters"
        >
          <FilterIcon className="h-3.5 w-3.5" /> Filter{appliedFilters.length ? ` (${appliedFilters.length})` : ""}
        </button>
        <button className="btn-ghost rounded-lg px-2 py-1.5 text-xs" onClick={() => setReload((n) => n + 1)} title="Refresh"><RefreshIcon className="h-3.5 w-3.5" /></button>

        {/* Quick search */}
        <form className="relative min-w-[10rem] flex-1 sm:max-w-xs" onSubmit={(e) => { e.preventDefault(); applyFilters(); }}>
          <SearchIcon className="pointer-events-none absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-500" />
          <input className="input py-1.5 pl-8 text-xs" placeholder="Search this table…" value={search} onChange={(e) => setSearch(e.target.value)} />
        </form>

        <div className="ml-auto flex items-center gap-2 text-xs">
          {total != null && <span className="hidden text-slate-500 sm:inline">{total.toLocaleString()} row{total === 1 ? "" : "s"}{hasActiveFilter ? " (filtered)" : ""}</span>}
          <select className="input w-auto py-1 text-xs" value={pageSize} onChange={(e) => { setPageSize(Number(e.target.value)); setPage(0); }} title="Rows per page">
            {[25, 50, 100, 200].map((n) => <option key={n} value={n}>{n} / page</option>)}
          </select>
          <div className="flex items-center gap-1">
            <button className="btn-secondary px-2 py-1 text-xs disabled:opacity-40" disabled={busy || page === 0} onClick={() => setPage((p) => Math.max(0, p - 1))} title="Previous page"><ChevronIcon className="h-3.5 w-3.5 rotate-180" /></button>
            <PageJump page={page} maxPage={maxPage} onJump={(p) => setPage(p)} />
            <button className="btn-secondary px-2 py-1 text-xs disabled:opacity-40" disabled={busy || page >= maxPage} onClick={() => setPage((p) => p + 1)} title="Next page"><ChevronIcon className="h-3.5 w-3.5" /></button>
          </div>
        </div>
      </div>

      {/* Per-column filter panel */}
      {showFilters && data && data.columns.length > 0 && (
        <div className="mb-2 rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
          <div className="grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-3">
            {data.columns.map((c) => (
              <div key={c} className="min-w-0">
                <label className="mb-1 block truncate font-mono text-[10px] text-slate-500" title={c}>{c}</label>
                <input
                  className="input py-1.5 text-xs"
                  placeholder="contains…"
                  value={colFilters[c] ?? ""}
                  onChange={(e) => setColFilters((f) => ({ ...f, [c]: e.target.value }))}
                  onKeyDown={(e) => { if (e.key === "Enter") applyFilters(); }}
                />
              </div>
            ))}
          </div>
          <div className="mt-2.5 flex items-center gap-2">
            <button className="btn-primary px-3 py-1.5 text-xs" onClick={applyFilters}>Apply filters</button>
            <button className="btn-ghost px-3 py-1.5 text-xs" onClick={clearFilters} disabled={!hasActiveFilter && Object.keys(colFilters).length === 0 && !search}>Clear all</button>
            <span className="text-[11px] text-slate-500">Filters match with LIKE and combine with AND.</span>
          </div>
        </div>
      )}

      {/* Selection action bar */}
      {selected.size > 0 && (
        <div className="mb-2 flex items-center gap-2 rounded-xl border border-brand-500/25 bg-brand-500/[0.08] px-3 py-2">
          <span className="text-xs font-medium text-brand-100">{selected.size} selected</span>
          <button className="btn-danger px-2.5 py-1 text-xs" onClick={() => setConfirmBulk(true)}><TrashIcon className="h-3.5 w-3.5" /> Delete selected</button>
          <button className="btn-ghost px-2 py-1 text-xs" onClick={() => setSelected(new Set())}>Clear</button>
        </div>
      )}

      {err && <ErrorBanner msg={err} onClose={() => setErr("")} />}

      {busy && !data ? (
        <GridSkeleton />
      ) : data ? (
        <DataGrid
          columns={data.columns}
          rows={data.rows}
          numericCols={numericCols}
          sort={sort}
          onSort={toggleSort}
          selected={selected}
          onToggleRow={(i) => setSelected((s) => { const n = new Set(s); n.has(i) ? n.delete(i) : n.add(i); return n; })}
          onToggleAll={() => setSelected((s) => (s.size === data.rows.length ? new Set() : new Set(data.rows.map((_, i) => i))))}
          onEdit={(r) => setEditor({ mode: "edit", original: rowRecord(r) })}
          onClone={(r) => setEditor({ mode: "clone", original: cloneRecord(r) })}
          onDelete={(r) => setConfirmDel({ row: rowRecord(r), label: firstCells(r) })}
          canInlineEdit={!!structure && structure.primaryKey.length > 0}
          onInlineSave={inlineSave}
          truncated={data.truncated}
        />
      ) : null}

      {editor && structure && (
        <RowEditor
          mode={editor.mode === "edit" ? "edit" : "insert"}
          heading={editor.mode === "clone" ? `Clone row into ${table}` : editor.mode === "edit" ? `Edit row in ${table}` : `Insert row into ${table}`}
          table={table}
          structure={structure}
          original={editor.mode === "edit" ? editor.original : null}
          initial={editor.mode === "clone" ? editor.original : null}
          onClose={() => setEditor(null)}
          onSave={async (payload) => {
            if (editor.mode === "edit") {
              const res = await dbmgrUpdateRow(accountId, dbName, table, editor.original ?? {}, payload.changes);
              if (res.error) return res.error;
            } else {
              const res = await dbmgrInsertRow(accountId, dbName, table, payload.values);
              if (res.error) return res.error;
            }
            setEditor(null);
            setReload((n) => n + 1);
            onDataChanged();
            return null;
          }}
        />
      )}

      {confirmDel && (
        <ConfirmDialog
          title="Delete this row?"
          body={<>This permanently deletes the row <span className="font-mono text-slate-200">{confirmDel.label}</span>. This can’t be undone.</>}
          confirmLabel="Delete row"
          danger
          onCancel={() => setConfirmDel(null)}
          onConfirm={doDelete}
        />
      )}
      {confirmBulk && (
        <ConfirmDialog
          title={`Delete ${selected.size} rows?`}
          body={<>This permanently deletes the {selected.size} selected row{selected.size === 1 ? "" : "s"}. This can’t be undone.</>}
          confirmLabel={`Delete ${selected.size} row${selected.size === 1 ? "" : "s"}`}
          danger
          onCancel={() => setConfirmBulk(false)}
          onConfirm={doBulkDelete}
        />
      )}

      {busyMsg && <BusyOverlay msg={busyMsg} />}
    </div>
  );
}

function PageJump({ page, maxPage, onJump }: { page: number; maxPage: number; onJump: (p: number) => void }) {
  const [editing, setEditing] = useState(false);
  const [val, setVal] = useState("");
  if (editing) {
    return (
      <form
        onSubmit={(e) => { e.preventDefault(); const p = Math.max(0, Math.min(maxPage, (Number(val) || 1) - 1)); onJump(p); setEditing(false); }}
        className="flex items-center"
      >
        <input
          autoFocus
          className="input w-14 px-1.5 py-1 text-center text-[11px]"
          value={val}
          onChange={(e) => setVal(e.target.value.replace(/[^0-9]/g, ""))}
          onBlur={() => setEditing(false)}
          placeholder={String(page + 1)}
        />
      </form>
    );
  }
  return (
    <button
      type="button"
      className="min-w-[4.5rem] rounded-md px-1 text-center text-[11px] tabular-nums text-slate-400 hover:bg-white/[0.05] hover:text-slate-200"
      onClick={() => { setVal(String(page + 1)); setEditing(true); }}
      title="Jump to page"
    >
      {page + 1} / {maxPage + 1}
    </button>
  );
}

function ExportMenu({ onExport }: { onExport: (f: "sql" | "csv") => void }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const h = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false); };
    window.addEventListener("mousedown", h);
    return () => window.removeEventListener("mousedown", h);
  }, [open]);
  return (
    <div className="relative" ref={ref}>
      <button className="btn-secondary px-2.5 py-1.5 text-xs" onClick={() => setOpen((v) => !v)}>
        <DownloadIcon className="h-3.5 w-3.5" /> Export <ChevronIcon className="h-3 w-3 rotate-90" />
      </button>
      {open && (
        <div className="absolute left-0 z-30 mt-1 w-40 overflow-hidden rounded-xl border border-white/[0.08] bg-navy-900/95 py-1 shadow-[0_16px_48px_-16px_rgb(0_0_0_/_0.7)] backdrop-blur-xl">
          <button className="flex w-full items-center gap-2 px-3 py-1.5 text-left text-xs text-slate-300 hover:bg-white/[0.05]" onClick={() => { onExport("sql"); setOpen(false); }}><SqlIcon className="h-3.5 w-3.5 text-brand-300" /> SQL dump (.sql)</button>
          <button className="flex w-full items-center gap-2 px-3 py-1.5 text-left text-xs text-slate-300 hover:bg-white/[0.05]" onClick={() => { onExport("csv"); setOpen(false); }}><GridIcon className="h-3.5 w-3.5 text-brand-300" /> CSV (.csv)</button>
        </div>
      )}
    </div>
  );
}

/* ================================================================ DataGrid === */

function DataGrid({
  columns,
  rows,
  numericCols,
  sort,
  onSort,
  selected,
  onToggleRow,
  onToggleAll,
  onEdit,
  onClone,
  onDelete,
  canInlineEdit,
  onInlineSave,
  truncated,
}: {
  columns: string[];
  rows: string[][];
  numericCols: Set<string>;
  sort: Sort;
  onSort: (col: string) => void;
  selected: Set<number>;
  onToggleRow: (i: number) => void;
  onToggleAll: () => void;
  onEdit: (r: string[]) => void;
  onClone: (r: string[]) => void;
  onDelete: (r: string[]) => void;
  canInlineEdit: boolean;
  onInlineSave: (row: string[], col: string, value: DbCellValue) => Promise<string | null>;
  truncated: boolean;
}) {
  const [editing, setEditing] = useState<{ ri: number; ci: number } | null>(null);
  const [editVal, setEditVal] = useState("");
  const [editNull, setEditNull] = useState(false);
  const [saving, setSaving] = useState(false);
  const [expanded, setExpanded] = useState<Set<string>>(new Set());

  const allSelected = rows.length > 0 && selected.size === rows.length;

  function startEdit(ri: number, ci: number, raw: string) {
    if (!canInlineEdit) return;
    setEditing({ ri, ci });
    setEditNull(raw === NULL_CELL);
    setEditVal(raw === NULL_CELL ? "" : raw);
  }
  async function commitEdit() {
    if (!editing) return;
    const { ri, ci } = editing;
    const col = columns[ci];
    const current = rows[ri][ci];
    const nextVal: DbCellValue = editNull ? null : editVal;
    const currentNorm = current === NULL_CELL ? null : current;
    if ((nextVal === null ? null : String(nextVal)) === (currentNorm === null ? null : String(currentNorm))) { setEditing(null); return; }
    setSaving(true);
    const err = await onInlineSave(rows[ri], col, nextVal);
    setSaving(false);
    setEditing(null);
    if (err) alert(err); // eslint-disable-line no-alert -- inline-edit failure surfaces immediately
  }

  if (columns.length === 0) return <p className="text-xs text-slate-500">No columns.</p>;
  return (
    <div>
      <div className="max-h-[60vh] overflow-auto rounded-xl border border-white/[0.06]">
        <table className="min-w-full border-separate border-spacing-0 text-left text-xs">
          <thead className="sticky top-0 z-10">
            <tr>
              <th className="sticky left-0 z-20 w-9 border-b border-white/[0.06] bg-navy-900/95 px-2 py-2 backdrop-blur">
                <input type="checkbox" className="accent-brand-500" checked={allSelected} onChange={onToggleAll} title="Select all on this page" />
              </th>
              <th className="w-24 border-b border-white/[0.06] bg-navy-900/95 px-2 py-2 text-[10px] font-semibold uppercase tracking-wider text-slate-600 backdrop-blur">Actions</th>
              {columns.map((c, i) => {
                const active = sort?.col === c;
                return (
                  <th key={i} className="whitespace-nowrap border-b border-white/[0.06] bg-navy-900/95 px-3 py-2 backdrop-blur">
                    <button type="button" onClick={() => onSort(c)} className="group inline-flex items-center gap-1 font-semibold text-slate-300 hover:text-white">
                      {c}
                      <span className={`text-[10px] ${active ? "text-brand-300" : "text-slate-600 group-hover:text-slate-500"}`}>{active ? (sort!.dir === "ASC" ? "▲" : "▼") : "↕"}</span>
                    </button>
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 && (
              <tr><td colSpan={columns.length + 2} className="px-3 py-6 text-center text-slate-500">No rows match.</td></tr>
            )}
            {rows.map((r, ri) => {
              const isSel = selected.has(ri);
              return (
                <tr key={ri} className={`transition-colors ${isSel ? "bg-brand-500/[0.08]" : "odd:bg-white/[0.01] hover:bg-white/[0.03]"}`}>
                  <td className={`sticky left-0 z-10 border-t border-white/[0.04] px-2 py-1 ${isSel ? "bg-brand-500/[0.08]" : "bg-navy-900/95"}`}>
                    <input type="checkbox" className="accent-brand-500" checked={isSel} onChange={() => onToggleRow(ri)} />
                  </td>
                  <td className="whitespace-nowrap border-t border-white/[0.04] px-2 py-1">
                    <div className="flex items-center gap-0.5">
                      <button type="button" onClick={() => onEdit(r)} className="rounded-md p-1 text-slate-500 hover:bg-brand-500/15 hover:text-brand-200" title="Edit row"><EditIcon className="h-3.5 w-3.5" /></button>
                      <button type="button" onClick={() => onClone(r)} className="rounded-md p-1 text-slate-500 hover:bg-brand-500/15 hover:text-brand-200" title="Clone row"><CopyIcon className="h-3.5 w-3.5" /></button>
                      <button type="button" onClick={() => onDelete(r)} className="rounded-md p-1 text-slate-500 hover:bg-red-500/15 hover:text-red-300" title="Delete row"><TrashIcon className="h-3.5 w-3.5" /></button>
                    </div>
                  </td>
                  {columns.map((col, ci) => {
                    const raw = r[ci];
                    const isNull = raw === NULL_CELL;
                    const numeric = numericCols.has(col);
                    const key = `${ri}:${ci}`;
                    const isExpanded = expanded.has(key);
                    const isEditingCell = editing?.ri === ri && editing?.ci === ci;
                    if (isEditingCell) {
                      return (
                        <td key={ci} className="border-t border-white/[0.03] px-1.5 py-1">
                          <div className="flex items-center gap-1">
                            <input
                              autoFocus
                              className="input w-full px-2 py-1 font-mono text-[11px] disabled:opacity-40"
                              disabled={editNull || saving}
                              value={editVal}
                              onChange={(e) => setEditVal(e.target.value)}
                              onKeyDown={(e) => { if (e.key === "Enter") commitEdit(); if (e.key === "Escape") setEditing(null); }}
                              onBlur={commitEdit}
                            />
                            <label className="flex shrink-0 cursor-pointer items-center gap-0.5 text-[10px] text-slate-400" title="Set NULL" onMouseDown={(e) => e.preventDefault()}>
                              <input type="checkbox" className="accent-brand-500" checked={editNull} onChange={(e) => setEditNull(e.target.checked)} />N
                            </label>
                          </div>
                        </td>
                      );
                    }
                    return (
                      <td
                        key={ci}
                        onDoubleClick={() => startEdit(ri, ci, raw)}
                        className={`border-t border-white/[0.03] px-3 py-1.5 font-mono text-slate-300 ${numeric ? "text-right tabular-nums" : ""} ${isExpanded ? "max-w-none whitespace-pre-wrap break-words" : "max-w-[24rem] truncate"} ${canInlineEdit ? "cursor-text" : ""}`}
                        title={canInlineEdit ? "Double-click to edit" : cell(raw)}
                      >
                        {isNull ? (
                          <span className="italic text-slate-600">NULL</span>
                        ) : (
                          <span className="inline-flex max-w-full items-center gap-1">
                            <span className={isExpanded ? "" : "truncate"}>{cell(raw)}</span>
                            {!isExpanded && (raw ?? "").length > 60 && (
                              <button type="button" className="shrink-0 text-slate-600 hover:text-brand-300" title="Expand" onClick={(e) => { e.stopPropagation(); setExpanded((s) => new Set(s).add(key)); }}>⋯</button>
                            )}
                            {isExpanded && (
                              <button type="button" className="shrink-0 text-slate-600 hover:text-brand-300" title="Collapse" onClick={(e) => { e.stopPropagation(); setExpanded((s) => { const n = new Set(s); n.delete(key); return n; }); }}>▲</button>
                            )}
                          </span>
                        )}
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div className="mt-1.5 flex flex-wrap items-center justify-between gap-2">
        {canInlineEdit ? (
          <p className="text-[11px] text-slate-600">Tip: double-click a cell to edit it inline.</p>
        ) : (
          <p className="text-[11px] text-slate-600">Inline editing needs a primary key — use the row editor instead.</p>
        )}
        {truncated && <p className="text-[11px] text-amber-300">Results truncated at the row/size cap — narrow with a filter or the SQL tab.</p>}
      </div>
    </div>
  );
}

/* ============================================================ StructureView === */

function StructureView({ accountId, dbName, table, onChanged, onEditData }: { accountId: string; dbName: string; table: string; onChanged: (o?: { removed?: string; renamedTo?: string }) => void; onEditData: () => void }) {
  const [structure, setStructure] = useState<DbMgrStructure | null>(null);
  const [createSql, setCreateSql] = useState<string>("");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(true);
  const [showCreate, setShowCreate] = useState(false);

  // Table-operation modal state.
  const [op, setOp] = useState<null | "rename" | "addColumn" | "addIndex">(null);
  const [confirm, setConfirm] = useState<null | { kind: "truncate" | "drop" | "dropColumn" | "dropIndex"; target?: string }>(null);
  const [busyMsg, setBusyMsg] = useState("");
  const [opErr, setOpErr] = useState("");

  const load = useCallback(async () => {
    setBusy(true); setErr("");
    const r = await dbmgrTableStructure(accountId, dbName, table);
    setBusy(false);
    if (r.error) { setErr(r.error); return; }
    setStructure(r.structure ?? null);
  }, [accountId, dbName, table]);
  useEffect(() => { load(); }, [load]);

  // SHOW CREATE TABLE via the SQL surface (read-only).
  useEffect(() => {
    let cancelled = false;
    dbmgrRunSql(accountId, dbName, `SHOW CREATE TABLE \`${table.replace(/`/g, "``")}\`;`).then((res) => {
      if (cancelled || res.error) return;
      setCreateSql(res.rows[0]?.[1] ?? "");
    });
    return () => { cancelled = true; };
  }, [accountId, dbName, table]);

  async function run(fn: () => Promise<{ error: string | null }>, msg: string, after?: () => void) {
    setBusyMsg(msg); setOpErr("");
    const res = await fn();
    setBusyMsg("");
    if (res.error) { setOpErr(res.error); return; }
    setConfirm(null); setOp(null);
    after?.();
  }

  if (busy) return <GridSkeleton />;
  if (err) return <ErrorBanner msg={err} onClose={() => setErr("")} />;
  if (!structure) return <p className="text-xs text-slate-500">No structure available.</p>;

  return (
    <div className="space-y-4">
      {opErr && <ErrorBanner msg={opErr} onClose={() => setOpErr("")} />}

      {/* Columns */}
      <div>
        <div className="mb-2 flex items-center justify-between">
          <p className="section-label">Columns <span className="text-slate-600">({structure.columns.length})</span></p>
          <button className="btn-secondary px-2.5 py-1 text-xs" onClick={() => { setOpErr(""); setOp("addColumn"); }}><PlusIcon className="h-3.5 w-3.5" /> Add column</button>
        </div>
        <div className="overflow-x-auto rounded-xl border border-white/[0.06]">
          <table className="min-w-full text-left text-xs">
            <thead className="bg-white/[0.03]">
              <tr>
                {["Column", "Type", "Null", "Key", "Default", "Extra", "Collation", ""].map((h) => (
                  <th key={h} className="whitespace-nowrap border-b border-white/[0.06] px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {structure.columns.map((c) => (
                <tr key={c.name} className="border-t border-white/[0.04] odd:bg-white/[0.01]">
                  <td className="whitespace-nowrap px-3 py-1.5 font-mono font-medium text-slate-200">
                    <span className="inline-flex items-center gap-1.5">{c.key === "PRI" && <KeyIcon className="h-3 w-3 text-amber-300" />}{c.name}</span>
                  </td>
                  <td className="whitespace-nowrap px-3 py-1.5 font-mono text-brand-200/90">{c.type}</td>
                  <td className="px-3 py-1.5 text-slate-400">{c.nullable ? "YES" : "NO"}</td>
                  <td className="px-3 py-1.5">{keyBadge(c)}</td>
                  <td className="whitespace-nowrap px-3 py-1.5 font-mono text-slate-400">{c.default === null ? <span className="italic text-slate-600">NULL</span> : c.default === "" ? <span className="text-slate-600">·</span> : c.default}</td>
                  <td className="whitespace-nowrap px-3 py-1.5 text-slate-500">{c.extra || "·"}</td>
                  <td className="whitespace-nowrap px-3 py-1.5 font-mono text-[11px] text-slate-500">{c.comment ? c.comment : "·"}</td>
                  <td className="px-2 py-1.5 text-right">
                    <button
                      type="button"
                      className="rounded-md p-1 text-slate-600 hover:bg-red-500/15 hover:text-red-300 disabled:opacity-30"
                      disabled={structure.columns.length <= 1}
                      title={structure.columns.length <= 1 ? "A table needs at least one column" : "Drop column"}
                      onClick={() => { setOpErr(""); setConfirm({ kind: "dropColumn", target: c.name }); }}
                    ><TrashIcon className="h-3.5 w-3.5" /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Indexes */}
      <div>
        <div className="mb-2 flex items-center justify-between">
          <p className="section-label">Indexes</p>
          <button className="btn-secondary px-2.5 py-1 text-xs" onClick={() => { setOpErr(""); setOp("addIndex"); }}><PlusIcon className="h-3.5 w-3.5" /> Add index</button>
        </div>
        {structure.indexes.length === 0 ? (
          <p className="text-xs text-slate-500">This table has no indexes.</p>
        ) : (
          <div className="overflow-x-auto rounded-xl border border-white/[0.06]">
            <table className="min-w-full text-left text-xs">
              <thead className="bg-white/[0.03]">
                <tr>
                  {["Name", "Columns", "Unique", ""].map((h) => (
                    <th key={h} className="border-b border-white/[0.06] px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {structure.indexes.map((ix) => (
                  <tr key={ix.name} className="border-t border-white/[0.04] odd:bg-white/[0.01]">
                    <td className="whitespace-nowrap px-3 py-1.5 font-mono text-slate-200">{ix.name === "PRIMARY" ? <Badge tone="amber">PRIMARY</Badge> : ix.name}</td>
                    <td className="px-3 py-1.5 font-mono text-slate-400">{ix.columns.join(", ")}</td>
                    <td className="px-3 py-1.5">{ix.unique ? <Badge tone="brand">unique</Badge> : <span className="text-slate-500">·</span>}</td>
                    <td className="px-2 py-1.5 text-right">
                      {ix.name !== "PRIMARY" && (
                        <button type="button" className="rounded-md p-1 text-slate-600 hover:bg-red-500/15 hover:text-red-300" title="Drop index" onClick={() => { setOpErr(""); setConfirm({ kind: "dropIndex", target: ix.name }); }}><TrashIcon className="h-3.5 w-3.5" /></button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* CREATE TABLE */}
      {createSql && (
        <div>
          <button className="section-label mb-2 inline-flex items-center gap-1.5 hover:text-slate-300" onClick={() => setShowCreate((v) => !v)}>
            <ChevronIcon className={`h-3 w-3 transition-transform ${showCreate ? "rotate-90" : ""}`} /> SHOW CREATE TABLE
          </button>
          {showCreate && (
            <pre className="max-h-64 overflow-auto rounded-xl border border-white/[0.06] bg-navy-950/60 p-3 font-mono text-[11px] leading-relaxed text-slate-300">{createSql}</pre>
          )}
        </div>
      )}

      {/* Table operations */}
      <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
        <p className="section-label mb-2 flex items-center gap-1.5"><WrenchIcon className="h-3.5 w-3.5" /> Table operations</p>
        <div className="flex flex-wrap gap-2">
          <button className="btn-secondary px-2.5 py-1.5 text-xs" onClick={() => run(() => dbmgrMaintainTable(accountId, dbName, table, "OPTIMIZE"), "Optimizing table…", load)}>Optimize</button>
          <button className="btn-secondary px-2.5 py-1.5 text-xs" onClick={() => run(() => dbmgrMaintainTable(accountId, dbName, table, "ANALYZE"), "Analyzing table…", load)}>Analyze</button>
          <button className="btn-secondary px-2.5 py-1.5 text-xs" onClick={() => { setOpErr(""); setOp("rename"); }}>Rename…</button>
          <button className="btn-danger px-2.5 py-1.5 text-xs" onClick={() => { setOpErr(""); setConfirm({ kind: "truncate" }); }}>Truncate…</button>
          <button className="btn-danger px-2.5 py-1.5 text-xs" onClick={() => { setOpErr(""); setConfirm({ kind: "drop" }); }}>Drop table…</button>
        </div>
      </div>

      {/* ── Op modals ── */}
      {op === "rename" && (
        <RenameDialog table={table} onCancel={() => setOp(null)} err={opErr}
          onRename={(to) => run(() => dbmgrRenameTable(accountId, dbName, table, to), "Renaming table…", () => onChanged({ renamedTo: to }))} />
      )}
      {op === "addColumn" && (
        <AddColumnDialog onCancel={() => setOp(null)} err={opErr}
          onAdd={(name, type, nullable) => run(() => dbmgrAddColumn(accountId, dbName, table, name, type, nullable), "Adding column…", load)} />
      )}
      {op === "addIndex" && (
        <AddIndexDialog columns={structure.columns.map((c) => c.name)} onCancel={() => setOp(null)} err={opErr}
          onAdd={(name, cols, unique) => run(() => dbmgrAddIndex(accountId, dbName, table, name, cols, unique), "Adding index…", load)} />
      )}

      {confirm?.kind === "truncate" && (
        <TypedConfirmDialog
          title="Truncate table?"
          body={<>This <span className="font-semibold text-red-300">permanently deletes every row</span> in <span className="font-mono text-slate-200">{table}</span> (the structure stays). This can’t be undone.</>}
          match={table} confirmLabel="Truncate table" err={opErr}
          onCancel={() => setConfirm(null)}
          onConfirm={() => run(() => dbmgrTruncateTable(accountId, dbName, table), "Truncating table…", () => { load(); onChanged(); onEditData(); })}
        />
      )}
      {confirm?.kind === "drop" && (
        <TypedConfirmDialog
          title="Drop table?"
          body={<>This <span className="font-semibold text-red-300">permanently deletes the table</span> <span className="font-mono text-slate-200">{table}</span> and all its data. This can’t be undone.</>}
          match={table} confirmLabel="Drop table" err={opErr}
          onCancel={() => setConfirm(null)}
          onConfirm={() => run(() => dbmgrDropTable(accountId, dbName, table), "Dropping table…", () => onChanged({ removed: table }))}
        />
      )}
      {confirm?.kind === "dropColumn" && confirm.target && (
        <ConfirmDialog
          title="Drop column?"
          body={<>This permanently deletes the column <span className="font-mono text-slate-200">{confirm.target}</span> and its data. This can’t be undone.</>}
          confirmLabel="Drop column" danger
          onCancel={() => setConfirm(null)}
          onConfirm={() => run(() => dbmgrDropColumn(accountId, dbName, table, confirm.target!), "Dropping column…", load)}
        />
      )}
      {confirm?.kind === "dropIndex" && confirm.target && (
        <ConfirmDialog
          title="Drop index?"
          body={<>This drops the index <span className="font-mono text-slate-200">{confirm.target}</span>. The data is untouched.</>}
          confirmLabel="Drop index" danger
          onCancel={() => setConfirm(null)}
          onConfirm={() => run(() => dbmgrDropIndex(accountId, dbName, table, confirm.target!), "Dropping index…", load)}
        />
      )}

      {busyMsg && <BusyOverlay msg={busyMsg} />}
    </div>
  );
}

/* ─────────────────────── Structure-op dialogs ─────────────────────── */

function RenameDialog({ table, onRename, onCancel, err }: { table: string; onRename: (to: string) => void; onCancel: () => void; err: string }) {
  const [to, setTo] = useState(table);
  return (
    <Modal title={`Rename ${table}`} onClose={onCancel}>
      <label className="label">New table name</label>
      <input className="input font-mono text-xs" autoFocus value={to} onChange={(e) => setTo(e.target.value)} placeholder="new_table_name" />
      <p className="mt-1 text-[11px] text-slate-500">Letters, digits and underscores only.</p>
      {err && <p className="mt-2 rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 font-mono text-[11px] text-red-200">{err}</p>}
      <div className="mt-4 flex items-center justify-end gap-2">
        <button className="btn-ghost px-3 py-2 text-xs" onClick={onCancel}>Cancel</button>
        <button className="btn-primary px-4 py-2 text-xs" disabled={!to.trim() || to === table} onClick={() => onRename(to.trim())}>Rename</button>
      </div>
    </Modal>
  );
}

function AddColumnDialog({ onAdd, onCancel, err }: { onAdd: (name: string, type: string, nullable: boolean) => void; onCancel: () => void; err: string }) {
  const [name, setName] = useState("");
  const [type, setType] = useState("VARCHAR(255)");
  const [nullable, setNullable] = useState(true);
  return (
    <Modal title="Add column" onClose={onCancel}>
      <div className="space-y-3">
        <div>
          <label className="label">Column name</label>
          <input className="input font-mono text-xs" autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="new_column" />
        </div>
        <div>
          <label className="label">Type</label>
          <input className="input font-mono text-xs" value={type} onChange={(e) => setType(e.target.value)} placeholder="VARCHAR(255)" list="dbmgr-types" />
          <datalist id="dbmgr-types">
            {["INT", "BIGINT", "DECIMAL(10,2)", "VARCHAR(255)", "TEXT", "DATE", "DATETIME", "TIMESTAMP", "BOOLEAN", "JSON"].map((t) => <option key={t} value={t} />)}
          </datalist>
          <p className="mt-1 text-[11px] text-slate-500">Base type with optional length, e.g. VARCHAR(255), INT, DECIMAL(10,2).</p>
        </div>
        <label className="flex cursor-pointer items-center gap-2 text-xs text-slate-300">
          <input type="checkbox" className="accent-brand-500" checked={nullable} onChange={(e) => setNullable(e.target.checked)} /> Allow NULL
        </label>
      </div>
      {err && <p className="mt-2 rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 font-mono text-[11px] text-red-200">{err}</p>}
      <div className="mt-4 flex items-center justify-end gap-2">
        <button className="btn-ghost px-3 py-2 text-xs" onClick={onCancel}>Cancel</button>
        <button className="btn-primary px-4 py-2 text-xs" disabled={!name.trim() || !type.trim()} onClick={() => onAdd(name.trim(), type.trim(), nullable)}>Add column</button>
      </div>
    </Modal>
  );
}

function AddIndexDialog({ columns, onAdd, onCancel, err }: { columns: string[]; onAdd: (name: string, cols: string[], unique: boolean) => void; onCancel: () => void; err: string }) {
  const [name, setName] = useState("");
  const [picked, setPicked] = useState<Set<string>>(new Set());
  const [unique, setUnique] = useState(false);
  const cols = [...picked];
  const suggested = name.trim() || (cols.length ? `idx_${cols.join("_")}`.slice(0, 64) : "");
  return (
    <Modal title="Add index" onClose={onCancel} wide>
      <div className="space-y-3">
        <div>
          <label className="label">Index name</label>
          <input className="input font-mono text-xs" value={name} onChange={(e) => setName(e.target.value)} placeholder={cols.length ? `idx_${cols.join("_")}` : "idx_name"} />
        </div>
        <div>
          <label className="label">Columns</label>
          <div className="max-h-48 space-y-1 overflow-y-auto rounded-lg border border-white/[0.06] bg-navy-900/50 p-2">
            {columns.map((c) => (
              <label key={c} className="flex cursor-pointer items-center gap-2 rounded-md px-1.5 py-1 font-mono text-xs text-slate-300 hover:bg-white/[0.04]">
                <input type="checkbox" className="accent-brand-500" checked={picked.has(c)} onChange={() => setPicked((s) => { const n = new Set(s); n.has(c) ? n.delete(c) : n.add(c); return n; })} />{c}
              </label>
            ))}
          </div>
        </div>
        <label className="flex cursor-pointer items-center gap-2 text-xs text-slate-300">
          <input type="checkbox" className="accent-brand-500" checked={unique} onChange={(e) => setUnique(e.target.checked)} /> Unique index
        </label>
      </div>
      {err && <p className="mt-2 rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 font-mono text-[11px] text-red-200">{err}</p>}
      <div className="mt-4 flex items-center justify-end gap-2">
        <button className="btn-ghost px-3 py-2 text-xs" onClick={onCancel}>Cancel</button>
        <button className="btn-primary px-4 py-2 text-xs" disabled={cols.length === 0 || !suggested} onClick={() => onAdd(suggested, cols, unique)}>Add index</button>
      </div>
    </Modal>
  );
}

/* =============================================================== RowEditor === */

type FieldState = { value: string; isNull: boolean; include: boolean };

function RowEditor({
  mode,
  heading,
  table,
  structure,
  original,
  initial,
  onClose,
  onSave,
}: {
  mode: "insert" | "edit";
  heading: string;
  table: string;
  structure: DbMgrStructure;
  original: Record<string, DbCellValue> | null;
  initial?: Record<string, DbCellValue> | null;
  onClose: () => void;
  onSave: (payload: { values: Record<string, DbCellValue>; changes: Record<string, DbCellValue> }) => Promise<string | null>;
}) {
  const [fields, setFields] = useState<Record<string, FieldState>>(() => {
    const init: Record<string, FieldState> = {};
    for (const c of structure.columns) {
      if (mode === "edit" && original) {
        const v = original[c.name];
        init[c.name] = { value: v === null ? "" : (v ?? ""), isNull: v === null, include: true };
      } else if (initial && c.name in initial) {
        const v = initial[c.name];
        init[c.name] = { value: v === null ? "" : (v ?? ""), isNull: v === null, include: true };
      } else {
        // Insert: pre-omit auto_increment / defaulted columns so the DB fills them.
        const auto = /auto_increment/i.test(c.extra) || c.default !== null;
        init[c.name] = { value: "", isNull: false, include: !auto };
      }
    }
    return init;
  });
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  function set(name: string, patch: Partial<FieldState>) {
    setFields((f) => ({ ...f, [name]: { ...f[name], ...patch } }));
  }

  async function submit() {
    setBusy(true); setErr("");
    const values: Record<string, DbCellValue> = {};
    const changes: Record<string, DbCellValue> = {};
    for (const c of structure.columns) {
      const f = fields[c.name];
      const val: DbCellValue = f.isNull ? null : f.value;
      if (mode === "insert") {
        if (f.include) values[c.name] = val;
      } else {
        const orig = original ? original[c.name] ?? null : null;
        const origNorm = orig === null ? null : String(orig);
        const nextNorm = f.isNull ? null : f.value;
        if (origNorm !== nextNorm) changes[c.name] = val;
      }
    }
    if (mode === "edit" && Object.keys(changes).length === 0) { setBusy(false); setErr("No changes to save."); return; }
    if (mode === "insert" && Object.keys(values).length === 0) { setBusy(false); setErr("Set at least one column."); return; }
    const e = await onSave({ values, changes });
    setBusy(false);
    if (e) setErr(e);
  }

  return (
    <Modal onClose={onClose} title={heading} wide>
      <div className="max-h-[60vh] space-y-2.5 overflow-y-auto pr-1">
        {structure.columns.map((c) => {
          const f = fields[c.name];
          return (
            <div key={c.name} className="grid grid-cols-[10rem_1fr] items-start gap-3">
              <div className="pt-2">
                <p className="flex items-center gap-1.5 font-mono text-xs text-slate-200">
                  {c.key === "PRI" && <KeyIcon className="h-3 w-3 text-amber-300" />}{c.name}
                </p>
                <p className="mt-0.5 font-mono text-[10px] text-slate-500">{c.type}{/auto_increment/i.test(c.extra) ? " · auto" : ""}{!c.nullable ? " · not null" : ""}</p>
              </div>
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  {isTextarea(c) ? (
                    <textarea className="input h-20 font-mono text-xs disabled:opacity-40" disabled={f.isNull} value={f.value} onChange={(e) => set(c.name, { value: e.target.value, include: true })} />
                  ) : (
                    <input className="input py-2 font-mono text-xs disabled:opacity-40" disabled={f.isNull} value={f.value} placeholder={mode === "insert" && !f.include ? "(default)" : ""} onChange={(e) => set(c.name, { value: e.target.value, include: true })} />
                  )}
                  {c.nullable && (
                    <label className="flex shrink-0 cursor-pointer items-center gap-1 text-[11px] text-slate-400">
                      <input type="checkbox" checked={f.isNull} onChange={(e) => set(c.name, { isNull: e.target.checked, include: true })} className="accent-brand-500" /> NULL
                    </label>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
      {err && <p className="mt-3 whitespace-pre-wrap rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 font-mono text-[11px] text-red-200">{err}</p>}
      <div className="mt-4 flex items-center justify-end gap-2">
        <button className="btn-ghost px-3 py-2 text-xs" onClick={onClose} disabled={busy}>Cancel</button>
        <button className="btn-primary px-4 py-2 text-xs" onClick={submit} disabled={busy}>{busy ? "Saving…" : mode === "insert" ? "Save row" : "Save changes"}</button>
      </div>
    </Modal>
  );
}

/* ================================================================ SqlEditor === */

const DESTRUCTIVE_RE = /^\s*(drop|truncate|delete|alter|update|replace|grant|revoke|create)\b/i;

type HistItem = { sql: string; at: number };

function SqlEditor({ accountId, dbName, onChanged }: { accountId: string; dbName: string; onChanged: () => void }) {
  const [sql, setSql] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [note, setNote] = useState("");
  const [result, setResult] = useState<{ columns: string[]; rows: string[][]; truncated: boolean } | null>(null);
  const [pendingConfirm, setPendingConfirm] = useState(false);
  const [history, setHistory] = useState<HistItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const histKey = `nxeon-dbstudio-sqlhistory:${accountId}:${dbName}`;
  useEffect(() => {
    try { const raw = localStorage.getItem(histKey); if (raw) setHistory(JSON.parse(raw)); } catch { /* */ }
  }, [histKey]);

  function pushHistory(q: string) {
    const trimmed = q.trim();
    if (!trimmed) return;
    setHistory((h) => {
      const next = [{ sql: trimmed, at: Date.now() }, ...h.filter((x) => x.sql !== trimmed)].slice(0, 25);
      try { localStorage.setItem(histKey, JSON.stringify(next)); } catch { /* */ }
      return next;
    });
  }
  function clearHistory() {
    setHistory([]);
    try { localStorage.removeItem(histKey); } catch { /* */ }
  }

  async function execute() {
    setBusy(true); setErr(""); setNote(""); setResult(null); setPendingConfirm(false);
    const started = sql;
    const res = await dbmgrRunSql(accountId, dbName, started);
    setBusy(false);
    if (res.error) { setErr(res.error); pushHistory(started); return; }
    pushHistory(started);
    if (res.columns.length === 0) {
      setNote(`Statement executed successfully · ${res.elapsedMs} ms`);
      onChanged();
      return;
    }
    setResult({ columns: res.columns, rows: res.rows, truncated: res.truncated });
    setNote(`${res.rows.length} row${res.rows.length === 1 ? "" : "s"}${res.truncated ? "+" : ""} · ${res.elapsedMs} ms`);
  }

  function run() {
    if (!sql.trim()) return;
    if (DESTRUCTIVE_RE.test(sql)) { setPendingConfirm(true); return; }
    execute();
  }

  return (
    <div>
      <div className="mb-2 flex items-center justify-between gap-2">
        <div className="flex items-center gap-2 text-[11px] text-slate-500">
          <SqlIcon className="h-3.5 w-3.5 text-brand-300" />
          Running against <span className="font-mono text-slate-300">{dbName}</span> as your scoped database user.
        </div>
        <button className={`btn-ghost rounded-lg px-2 py-1 text-[11px] ${showHistory ? "text-brand-200" : ""}`} onClick={() => setShowHistory((v) => !v)} disabled={history.length === 0}>
          <HistoryIcon className="h-3.5 w-3.5" /> History{history.length ? ` (${history.length})` : ""}
        </button>
      </div>

      <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_auto]">
        <div>
          <div className="overflow-hidden rounded-xl border border-white/[0.08] focus-within:border-brand-400/50 focus-within:ring-2 focus-within:ring-brand-500/20">
            <textarea
              className="block h-52 w-full resize-y bg-navy-900/80 px-3.5 py-3 font-mono text-xs leading-relaxed text-slate-100 outline-none placeholder:text-slate-600"
              placeholder="SELECT * FROM your_table LIMIT 20;"
              spellCheck={false}
              value={sql}
              onChange={(e) => setSql(e.target.value)}
              onKeyDown={(e) => { if ((e.metaKey || e.ctrlKey) && e.key === "Enter") run(); }}
            />
          </div>
          <div className="mt-2 flex flex-wrap items-center gap-2">
            <button className="btn-primary px-4 py-1.5 text-xs" disabled={busy || !sql.trim()} onClick={run}><PlayIcon className="h-3.5 w-3.5" />{busy ? "Running…" : "Run"}</button>
            <span className="kbd">⌘/Ctrl + Enter</span>
            <button className="btn-ghost px-2 py-1.5 text-xs" disabled={busy || !sql} onClick={() => { setSql(""); setResult(null); setNote(""); setErr(""); }}>Clear</button>
            {note && <span className="ml-auto text-[11px] text-slate-400">{note}</span>}
          </div>
        </div>

        {showHistory && history.length > 0 && (
          <aside className="w-full lg:w-64">
            <div className="mb-1.5 flex items-center justify-between">
              <p className="section-label">Query history</p>
              <button className="text-[11px] text-slate-500 hover:text-red-300" onClick={clearHistory}>Clear</button>
            </div>
            <ul className="max-h-52 space-y-1 overflow-y-auto rounded-xl border border-white/[0.06] bg-white/[0.02] p-2">
              {history.map((h, i) => (
                <li key={i}>
                  <button
                    type="button"
                    onClick={() => setSql(h.sql)}
                    className="block w-full truncate rounded-md px-2 py-1.5 text-left font-mono text-[11px] text-slate-400 hover:bg-white/[0.05] hover:text-slate-200"
                    title={h.sql}
                  >{h.sql}</button>
                </li>
              ))}
            </ul>
          </aside>
        )}
      </div>

      {err && <div className="mt-3"><ErrorBanner msg={err} onClose={() => setErr("")} /></div>}
      {result && (
        <div className="mt-3">
          <ResultGrid columns={result.columns} rows={result.rows} truncated={result.truncated} />
        </div>
      )}

      {pendingConfirm && (
        <ConfirmDialog
          title="Run this statement?"
          body={<>This looks like it modifies data or schema. It runs as your scoped database user, but the change may be hard to undo. Continue?</>}
          confirmLabel="Run statement"
          danger
          onCancel={() => setPendingConfirm(false)}
          onConfirm={execute}
        />
      )}
    </div>
  );
}

function ResultGrid({ columns, rows, truncated }: { columns: string[]; rows: string[][]; truncated: boolean }) {
  if (columns.length === 0) return <p className="text-xs text-slate-500">No columns.</p>;
  return (
    <div>
      <div className="max-h-[55vh] overflow-auto rounded-xl border border-white/[0.06]">
        <table className="min-w-full border-separate border-spacing-0 text-left text-xs">
          <thead className="sticky top-0 z-10">
            <tr>{columns.map((c, i) => <th key={i} className="whitespace-nowrap border-b border-white/[0.06] bg-navy-900/95 px-3 py-2 font-semibold text-slate-300 backdrop-blur">{c}</th>)}</tr>
          </thead>
          <tbody>
            {rows.length === 0 && <tr><td colSpan={columns.length} className="px-3 py-4 text-center text-slate-500">No rows.</td></tr>}
            {rows.map((r, ri) => (
              <tr key={ri} className="odd:bg-white/[0.01] hover:bg-white/[0.03]">
                {columns.map((_, ci) => (
                  <td key={ci} className="max-w-[24rem] truncate border-t border-white/[0.03] px-3 py-1.5 font-mono text-slate-300" title={cell(r[ci])}>
                    {r[ci] === NULL_CELL ? <span className="italic text-slate-600">NULL</span> : cell(r[ci])}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {truncated && <p className="mt-1.5 text-[11px] text-amber-300">Results truncated — refine with a tighter LIMIT or WHERE to see more.</p>}
    </div>
  );
}

/* =============================================================== ImportPanel === */

type ImportRes = { sql: string; ok: boolean; error: string | null; rows: number; elapsedMs: number };

function ImportPanel({ accountId, dbName, onChanged }: { accountId: string; dbName: string; onChanged: () => void }) {
  const [sql, setSql] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [results, setResults] = useState<ImportRes[] | null>(null);
  const [ranAll, setRanAll] = useState(false);
  const [confirm, setConfirm] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  async function onFile(e: React.ChangeEvent<HTMLInputElement>) {
    const f = e.target.files?.[0];
    if (!f) return;
    if (f.size > 512 * 1024) { setErr("File is larger than 512 KB — split it into smaller scripts."); return; }
    const text = await f.text();
    setSql(text);
    setErr("");
    if (fileRef.current) fileRef.current.value = "";
  }

  async function doImport() {
    setConfirm(false);
    setBusy(true); setErr(""); setResults(null);
    const res = await dbmgrImportSql(accountId, dbName, sql);
    setBusy(false);
    if (res.error) { setErr(res.error); return; }
    setResults(res.results ?? []);
    setRanAll(!!res.ranAll);
    onChanged();
  }

  const okCount = results?.filter((r) => r.ok).length ?? 0;

  return (
    <div>
      <div className="mb-2 flex items-center gap-2 text-[11px] text-slate-500">
        <UploadIcon className="h-3.5 w-3.5 text-brand-300" />
        Import runs each statement on its own into <span className="font-mono text-slate-300">{dbName}</span> as your scoped user. It stops at the first error.
      </div>
      <div className="overflow-hidden rounded-xl border border-white/[0.08] focus-within:border-brand-400/50 focus-within:ring-2 focus-within:ring-brand-500/20">
        <textarea
          className="block h-44 w-full resize-y bg-navy-900/80 px-3.5 py-3 font-mono text-xs leading-relaxed text-slate-100 outline-none placeholder:text-slate-600"
          placeholder={"-- Paste SQL, or upload a .sql file\nCREATE TABLE example (id INT PRIMARY KEY, name VARCHAR(100));\nINSERT INTO example VALUES (1, 'first');"}
          spellCheck={false}
          value={sql}
          onChange={(e) => setSql(e.target.value)}
        />
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <button className="btn-primary px-4 py-1.5 text-xs" disabled={busy || !sql.trim()} onClick={() => setConfirm(true)}><PlayIcon className="h-3.5 w-3.5" />{busy ? "Importing…" : "Run import"}</button>
        <button className="btn-secondary px-3 py-1.5 text-xs" onClick={() => fileRef.current?.click()}><UploadIcon className="h-3.5 w-3.5" /> Upload .sql</button>
        <input ref={fileRef} type="file" accept=".sql,text/plain" className="hidden" onChange={onFile} />
        <button className="btn-ghost px-2 py-1.5 text-xs" disabled={busy || !sql} onClick={() => { setSql(""); setResults(null); setErr(""); }}>Clear</button>
      </div>

      {err && <div className="mt-3"><ErrorBanner msg={err} onClose={() => setErr("")} /></div>}

      {results && (
        <div className="mt-3">
          <div className={`mb-2 flex items-center gap-2 rounded-xl border px-3 py-2 text-xs ${ranAll ? "border-emerald-500/25 bg-emerald-500/[0.08] text-emerald-200" : "border-amber-500/25 bg-amber-500/[0.08] text-amber-200"}`}>
            {ranAll ? <CheckIcon className="h-4 w-4" /> : <WarnIcon className="h-4 w-4" />}
            {ranAll ? `Imported all ${results.length} statement${results.length === 1 ? "" : "s"} successfully.` : `Stopped after an error — ${okCount} of ${results.length} statement${results.length === 1 ? "" : "s"} ran.`}
          </div>
          <ol className="space-y-1.5">
            {results.map((r, i) => (
              <li key={i} className={`rounded-lg border px-3 py-2 ${r.ok ? "border-white/[0.06] bg-white/[0.02]" : "border-red-500/25 bg-red-500/[0.06]"}`}>
                <div className="flex items-start gap-2">
                  <span className={`mt-0.5 shrink-0 ${r.ok ? "text-emerald-400" : "text-red-400"}`}>{r.ok ? <CheckIcon className="h-3.5 w-3.5" /> : <XIcon className="h-3.5 w-3.5" />}</span>
                  <div className="min-w-0 flex-1">
                    <p className="truncate font-mono text-[11px] text-slate-300" title={r.sql}>{r.sql}</p>
                    {r.error ? (
                      <p className="mt-0.5 whitespace-pre-wrap font-mono text-[11px] text-red-300">{r.error}</p>
                    ) : (
                      <p className="mt-0.5 text-[10px] text-slate-500">{r.rows > 0 ? `${r.rows} row${r.rows === 1 ? "" : "s"} · ` : ""}{r.elapsedMs} ms</p>
                    )}
                  </div>
                </div>
              </li>
            ))}
          </ol>
        </div>
      )}

      {confirm && (
        <ConfirmDialog
          title="Run this import?"
          body={<>This runs the pasted SQL against <span className="font-mono text-slate-200">{dbName}</span>, statement by statement. Some statements may modify or delete data and can be hard to undo.</>}
          confirmLabel="Run import"
          danger
          onCancel={() => setConfirm(false)}
          onConfirm={doImport}
        />
      )}
    </div>
  );
}

/* ================================================================== shared === */

function TabButton({ active, disabled, onClick, icon, children }: { active: boolean; disabled?: boolean; onClick: () => void; icon: React.ReactNode; children: React.ReactNode }) {
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      className={`inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-40 ${active ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]" : "text-slate-400 hover:bg-white/[0.05] hover:text-white"}`}
    >
      {icon}{children}
    </button>
  );
}

function Modal({ title, children, onClose, wide }: { title: string; children: React.ReactNode; onClose: () => void; wide?: boolean }) {
  useEffect(() => {
    const h = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, [onClose]);
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true">
      <div className="absolute inset-0 bg-navy-950/70 backdrop-blur-sm" onClick={onClose} />
      <div className={`relative w-full ${wide ? "max-w-2xl" : "max-w-md"} rounded-2xl border border-white/[0.08] bg-navy-900/95 p-5 shadow-[0_24px_80px_-24px_rgb(0_0_0_/_0.8)] backdrop-blur-xl`}>
        <div className="mb-4 flex items-center justify-between">
          <h4 className="text-sm font-semibold text-slate-100">{title}</h4>
          <button className="btn-ghost rounded-md p-1" onClick={onClose}><XIcon className="h-4 w-4" /></button>
        </div>
        {children}
      </div>
    </div>
  );
}

function ConfirmDialog({ title, body, confirmLabel, danger, onCancel, onConfirm }: { title: string; body: React.ReactNode; confirmLabel: string; danger?: boolean; onCancel: () => void; onConfirm: () => void }) {
  return (
    <Modal title={title} onClose={onCancel}>
      <p className="text-sm text-slate-300">{body}</p>
      <div className="mt-5 flex items-center justify-end gap-2">
        <button className="btn-ghost px-3 py-2 text-xs" onClick={onCancel}>Cancel</button>
        <button className={`${danger ? "btn-danger" : "btn-primary"} px-4 py-2 text-xs`} onClick={onConfirm}>{confirmLabel}</button>
      </div>
    </Modal>
  );
}

/** A destructive-op confirm that requires the user to type an exact string
 *  (usually the table name) before the action arms — the phpMyAdmin-style guard
 *  against a mis-click truncating/dropping a table. */
function TypedConfirmDialog({ title, body, match, confirmLabel, err, onCancel, onConfirm }: { title: string; body: React.ReactNode; match: string; confirmLabel: string; err?: string; onCancel: () => void; onConfirm: () => void }) {
  const [val, setVal] = useState("");
  const armed = val === match;
  return (
    <Modal title={title} onClose={onCancel}>
      <p className="text-sm text-slate-300">{body}</p>
      <label className="label mt-4">Type <span className="font-mono text-slate-200">{match}</span> to confirm</label>
      <input className="input font-mono text-xs" autoFocus value={val} onChange={(e) => setVal(e.target.value)} placeholder={match} onKeyDown={(e) => { if (e.key === "Enter" && armed) onConfirm(); }} />
      {err && <p className="mt-2 rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 font-mono text-[11px] text-red-200">{err}</p>}
      <div className="mt-4 flex items-center justify-end gap-2">
        <button className="btn-ghost px-3 py-2 text-xs" onClick={onCancel}>Cancel</button>
        <button className="btn-danger px-4 py-2 text-xs disabled:opacity-40" disabled={!armed} onClick={onConfirm}>{confirmLabel}</button>
      </div>
    </Modal>
  );
}

function ErrorBanner({ msg, onClose }: { msg: string; onClose?: () => void }) {
  return (
    <div className="mb-3 flex items-start gap-2 rounded-xl border border-red-500/25 bg-red-500/[0.08] px-3 py-2">
      <WarnIcon className="mt-0.5 h-4 w-4 shrink-0 text-red-300" />
      <p className="flex-1 whitespace-pre-wrap font-mono text-[11px] text-red-200">{msg}</p>
      {onClose && <button className="text-red-300/70 hover:text-red-200" onClick={onClose}><XIcon className="h-3.5 w-3.5" /></button>}
    </div>
  );
}

function BusyOverlay({ msg }: { msg: string }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-navy-950/40 backdrop-blur-sm">
      <div className="flex items-center gap-3 rounded-xl border border-white/[0.08] bg-navy-900/95 px-5 py-3 shadow-xl">
