/* helpers */
const NULL_CELL = " NULL ";
function cell(v: string | undefined): string {
  if (v === undefined) return "";
  if (v === NULL_CELL) return "NULL";
  return v;
}
function firstCells(r: string[]): string {
  return r.slice(0, 3).map((c) => (c === NULL_CELL ? "NULL" : c)).join(", ") + (r.length > 3 ? "…" : "");
}
function fmtCount(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`;
  return String(n);
}
function fmtBytes(b: number): string {
  if (!b || b <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), units.length - 1);
  return `${(b / 1024 ** i).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
}
function isTextarea(c: DbMgrColumn): boolean {
  return /text|blob|json/i.test(c.type);
}
function isNumericType(type: string): boolean {
  return /^(tiny|small|medium|big)?int|^decimal|^numeric|^float|^double|^bit\b|^year/i.test(String(type).trim());
}
function keyBadge(c: DbMgrColumn) {
  if (c.key === "PRI") return <Badge tone="amber">PRIMARY</Badge>;
  if (c.key === "UNI") return <Badge tone="brand">unique</Badge>;
  if (c.key === "MUL") return <Badge tone="slate">index</Badge>;
  return <span className="text-slate-600">·</span>;
}
function downloadText(filename: string, text: string, mime = "text/plain") {
  const blob = new Blob([text], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/* ================================================================== icons === */
